import React from 'react';
import PropTypes from 'prop-types';

import Row from './row';

const Action = ({
	tabIndex,
	itemIndex,
	label = '',
	rowLabel = '',
	buttons,
	callButtonAction,
	focused = false,
	focusedButtonIndex = 0,
}) => {
	const handleClick = (idx, lbl) => (e) => {
		e.target.blur();
		callButtonAction(tabIndex, itemIndex, idx, lbl);
	};
	if (label === '') label = 'execute';
	const buttonLabels = Array.isArray(buttons) ? buttons : [label];
	if (Array.isArray(buttons)) rowLabel = '';

	return (
		<Row label={rowLabel} focused={focused}>
			<div className="col col-md-9">
				{buttonLabels.map((lbl, idx) => (
					<button
						key={idx}
						className={`btn btn-sm mr-1 btn-secondary ${
							focused && idx === focusedButtonIndex ? 'focused' : ''
						}`}
						onClick={handleClick(idx, lbl)}
					>
						{lbl}
					</button>
				))}
			</div>
		</Row>
	);
};

Action.propTypes = {
	tabIndex: PropTypes.string.isRequired,
	itemIndex: PropTypes.string.isRequired,
	label: PropTypes.string,
	rowLabel: PropTypes.string,
	text: PropTypes.string,
	buttons: PropTypes.arrayOf(PropTypes.string),
	callButtonAction: PropTypes.func.isRequired,
	focused: PropTypes.bool,
	focusedButtonIndex: PropTypes.number,
};

// Removed defaultProps in favor of default parameters

export default Action;
