import React from 'react';
import { createRoot } from 'react-dom/client';
import MainContainer from './containers/maincontainer';
import { merge } from 'lodash';
import cssText from '../../css/dynamicMenu.css?inline';

const STYLE_ID = 'dynamic-menu-styles';

function injectStyles() {
	if (document.getElementById(STYLE_ID)) return;
	const style = document.createElement('style');
	style.id = STYLE_ID;
	style.textContent = cssText;
	document.head.appendChild(style);
}

const defaultOptions = {
	enableTweening: false,
	onUiChange: null,
	notifyOnMount: false,
	collapsibleFolders: true,
	focusNavigation: false,
	dom: document,
};

/**
 * Mount a DynamicMenu into a DOM container and return its API.
 *
 * @param {HTMLElement} menuContainer - DOM element where the menu will be rendered.
 * @param {object}      [options={}]  - Optional configuration.
 * @param {boolean}     [options.enableTweening=false]  - Enable slider tween animation by default.
 * @param {Function}    [options.onUiChange=null]        - Initial callback fired on any UI change.
 *   Receives `{ tabIndex, itemIndex, type, value }`. Can be replaced later via `menu.onUiChange(cb)`.
 * @param {boolean}     [options.notifyOnMount=false]    - If true, fires `onUiChange` immediately
 *   after mount with the current state of every control.
 * @param {boolean}     [options.collapsibleFolders=true] - If true, folders created with
 *   `tab.addFolder()` can be collapsed/expanded by clicking their header. If false, folders
 *   are static visual groups (always open, non-interactive header) — avoids canvas resizes.
 * @param {boolean}     [options.focusNavigation=false]  - If true, enables device-agnostic
 *   focus navigation (`moveUp/moveDown/moveLeft/moveRight/activate`) so the menu can be driven
 *   by a D-pad, gamepad, VR joystick or keyboard via method calls — no hardware binding.
 * @returns {Promise<MenuAPI>} Resolves once the React component is mounted and the API is ready.
 *
 * @example
 * const menu = await createMenu(document.getElementById('menu-root'));
 * const settingsTab = menu.addTab('Settings', 'fa-cog');
 * const volumeItem  = settingsTab.addItem({ type: 'slider', label: 'Volume', min: 0, max: 1 });
 * volumeItem.onChange(v => console.log('volume:', v));
 */
export function createMenu(menuContainer, options = {}) {
	injectStyles();
	const opts = merge({}, defaultOptions, options);

	const root = createRoot(menuContainer);

	const menuRef = React.createRef();

	const onUiChangeRef = {
		current: typeof opts.onUiChange === 'function' ? opts.onUiChange : null,
	};

	const onUiChangeWrapper = (info) => {
		try {
			onUiChangeRef.current?.(info);
		} catch (e) {
			console.error(e);
		}
	};

	root.render(
		<MainContainer
			ref={menuRef}
			onUiChange={onUiChangeWrapper}
			notifyOnMount={opts.notifyOnMount}
			collapsibleFolders={opts.collapsibleFolders}
			focusNavigation={opts.focusNavigation}
		/>
	);

	return new Promise((resolve) => {
		const checkRef = () => {
			if (menuRef.current) {
				/**
				 * @typedef {object} MenuAPI
				 * The public interface returned by {@link createMenu}.
				 */
				resolve({
					/**
					 * Add a new tab to the menu.
					 * @param {string} tabName - Display label for the tab.
					 * @param {string} [icon]  - FontAwesome class (e.g. `'fa-cog'`) or raw Unicode glyph.
					 * @returns {TabHandler}
					 */
					addTab: (tabName, icon) => menuRef.current.addTab(tabName, icon),

					/**
					 * Remove a tab previously created with `addTab`.
					 * @param {TabHandler} tab - The handler returned by `addTab`.
					 */
					removeTab: (tab) => menuRef.current.removeTab(tab),

					/**
					 * Re-read all bound objects and push their current values to the menu.
					 * Call this after external code changes a bound property without going
					 * through the menu API.
					 */
					sync: () => menuRef.current.sync(),

					/**
					 * Whether device-agnostic focus navigation is enabled (set via the
					 * `focusNavigation` option). When false, all `move*`/`activate` calls
					 * are no-ops. Use this to decide whether to show a D-pad / wire input.
					 * @returns {boolean}
					 */
					isFocusNavEnabled: () => menuRef.current.isFocusNavEnabled(),

					/** Move keyboard/gamepad focus one row up. */
					moveUp: () => menuRef.current.moveUp(),
					/** Move keyboard/gamepad focus one row down. */
					moveDown: () => menuRef.current.moveDown(),
					/** Move focus left (e.g. previous button in a button row, previous tree option). */
					moveLeft: () => menuRef.current.moveLeft(),
					/** Move focus right. */
					moveRight: () => menuRef.current.moveRight(),

					/**
					 * Click the button targeted inside the focused action row.
					 * Does nothing when focus is not currently on a button control.
					 * @returns {{executed:boolean}}
					 */
					clickFocusedButton: () => menuRef.current.clickFocusedButton(),

					/**
					 * Activate the currently focused control.
					 * For buttons this fires the action; for switches it toggles; for sliders it
					 * commits the in-flight value.
					 */
					activate: () => menuRef.current.activate(),

					/**
					 * Press-and-hold a direction. Fires the matching action once immediately
					 * and then auto-repeats while held — e.g. holding `'left'`/`'right'` over a
					 * slider ramps its value gradually. Always pair with {@link release}.
					 * `'activate'` fires once and does not repeat.
					 *
					 * Wire this to a button's pointerdown / a key's keydown / a VR trigger press.
					 * @param {'up'|'down'|'left'|'right'|'activate'} direction
					 */
					press: (direction) => menuRef.current.press(direction),

					/**
					 * Release a previously {@link press}ed direction, stopping its auto-repeat.
					 * Wire to pointerup / pointerleave / keyup / VR trigger release.
					 * @param {'up'|'down'|'left'|'right'|'activate'} direction
					 */
					release: (direction) => menuRef.current.release(direction),

					/** Start a continuous adjustment session on the focused slider. */
					beginFocusedValueAdjustment: () => menuRef.current.beginFocusedValueAdjustment(),

					/**
					 * Adjust the captured slider by a fraction of its complete range.
					 * @param {number} normalizedDelta Signed fraction of the slider range.
					 * @returns {boolean} Whether the visible slider value changed.
					 */
					adjustFocusedValue: (normalizedDelta) => menuRef.current.adjustFocusedValue(normalizedDelta),

					/** Finish the active continuous adjustment session and commit its value. */
					endFocusedValueAdjustment: () => menuRef.current.endFocusedValueAdjustment(),

					/**
					 * Hide and reset the focus-navigation cursor. The next moveDown call
					 * reactivates it on the current tab in the top bar.
					 */
					deactivateFocusNavigation: () => menuRef.current.deactivateFocusNavigation(),

					/**
					 * Show or hide the menu panel.
					 * @param {boolean} visible
					 */
					setVisible: (visible) => menuRef.current.setVisible(visible),

					/**
					 * Update the options list of a select control at runtime.
					 *
					 * Accepts three calling signatures:
					 * - `updateSelectOptions(itemHandler, newOptions)`
					 * - `updateSelectOptions({ tabIndex, itemIndex }, newOptions)`
					 * - `updateSelectOptions(tabIndex, itemIndex, newOptions)`
					 *
					 * @param {ItemHandler|{tabIndex:number,itemIndex:number}|number} target
					 * @param {Array|object} [newOptionsOrItemIndex]
					 * @param {Array|object} [newOptions]
					 */
					updateSelectOptions: (...args) => {
						if (!args.length) {
							throw new Error('updateSelectOptions requires a target control');
						}

						const [target, maybeItemIndex, maybeOptions] = args;

						if (target && typeof target.updateOptions === 'function') {
							target.updateOptions(maybeItemIndex);
							return;
						}

						let tabIndex;
						let itemIndex;
						let options;

						if (target && typeof target === 'object' && 'tabIndex' in target && 'itemIndex' in target) {
							tabIndex = target.tabIndex;
							itemIndex = target.itemIndex;
							options = maybeItemIndex;
						} else {
							tabIndex = target;
							itemIndex = maybeItemIndex;
							options = maybeOptions;
						}

						if (tabIndex === undefined || itemIndex === undefined) {
							throw new Error('updateSelectOptions requires a valid target');
						}

						menuRef.current.updateSelectOptions(tabIndex, itemIndex, options);
					},
					/**
					 * Replace the UI-change callback. Pass `null` to disable.
					 * The callback receives `{ tabIndex, itemIndex, type, value }`.
					 * @param {Function|null} cb
					 */
					onUiChange: (cb) => {
						onUiChangeRef.current = typeof cb === 'function' ? cb : null;
					},

					/**
					 * Return a serializable snapshot of the full menu state.
					 * Pass this to `CanvasRenderer.setState()` to initialize the renderer.
					 * @returns {object} Menu state snapshot.
					 */
					getMenuState: () => menuRef.current.getMenuState(),

					/**
					 * Protocol/contract version this DynamicMenu build speaks. The same
					 * value is stamped onto every `getMenuState()` snapshot as `version`,
					 * and CanvasRenderer validates it on `setState()`. See `protocol.js`.
					 * @type {string}
					 */
					protocolVersion: menuRef.current.protocolVersion,

					/**
					 * Return a snapshot of only the currently visible tab's items.
					 * @returns {object}
					 */
					getVisibleTabState: () => menuRef.current.getVisibleTabState(),

					/**
					 * Subscribe to menu events (used internally by `CanvasRenderer`).
					 * The listener is called with an event object:
					 * `{ type: 'tabChange'|'structureChange'|'controlChange'|'controlCommit'|'visibilityChange', ... }`
					 * @param {Function} listener
					 */
					subscribe: (listener) => menuRef.current.subscribe(listener),

					/**
					 * Remove a previously registered listener.
					 * @param {Function} listener
					 */
					unsubscribe: (listener) => menuRef.current.unsubscribe(listener),

					/**
					 * Execute a logical command — the same command objects emitted by
					 * `CanvasRenderer.onCommand`. Use this to wire canvas pointer
					 * interactions back into the DynamicMenu state.
					 *
					 * Supported commands:
					 * - `{ type: 'set-tab', tabId }`
					 * - `{ type: 'cycle', tabId, itemId, payload: { direction: 'prev'|'next' } }`
					 * - `{ type: 'toggle', tabId, itemId }`
					 * - `{ type: 'toggle-folder', tabId, itemId }`
					 * - `{ type: 'activate', tabId, itemId, payload: { buttonIndex, buttonLabel } }`
					 * - `{ type: 'set-slider-raw', tabId, itemId, payload: { rawValue } }`
					 * - `{ type: 'set-value', tabId, itemId, payload: { value } }`
					 *
					 * @param {object} cmd - Command object.
					 */
					executeCommand: (cmd) => menuRef.current.executeCommand(cmd),

					/**
					 * Programmatically switch to a tab by its ID.
					 * @param {string} tabId
					 */
					setCurrentTab: (tabId) => menuRef.current.setCurrentTab(tabId),
				});
			} else {
				setTimeout(checkRef, 0);
			}
		};
		checkRef();
	});
}

window.createMenu = createMenu;
