/**
 * @class ItemHandler
 * @classdesc Handle returned by `tab.addItem()`. Use it to react to value
 * changes and, for select controls, to update the options list at runtime.
 *
 * @example
 * const vol = tab.addItem({ type: 'slider', label: 'Volume', min: 0, max: 1 });
 * vol.onChange(v => console.log('volume changed to', v));
 *
 * // Update a select's options later:
 * const mode = tab.addItem({ type: 'select', label: 'Mode', options: ['A', 'B'] });
 * mode.updateOptions(['A', 'B', 'C']);
 */
function ItemHandler(tabIndex, itemIndex, updateOptionsRef) {
        let me = this;

        /**
         * Zero-based index of this item within its tab.
         * @type {number}
         */
        me.itemIndex = itemIndex;

        /**
         * Zero-based index of the parent tab.
         * @type {number}
         */
        me.tabIndex = tabIndex;

        me.onChangeCallback;
        me.listening = false;

        /**
         * Register a callback that fires whenever the control's value changes.
         * For sliders this fires on commit (pointer-up / Enter), not on every drag frame.
         * @function onChange
         * @memberof ItemHandler#
         * @param {Function} callback - Called with `(value)`.
         * @returns {ItemHandler} `this` for chaining.
         */
        me.onChange = function (callback) {
                this.onChangeCallback = callback;
                return me;
        };

        /**
         * Internal — called by the menu to dispatch a value change to the registered callback.
         * @param {*} v - New value.
         */
        me.dispatchOnChange = function (v) {
                if (me.onChangeCallback) {
                        me.onChangeCallback(v);
                }
        };

        /**
         * Mark this item as "listening" so that `menu.sync()` will read its bound
         * object property and push the value back into the menu.
         * @function listen
         * @memberof ItemHandler#
         * @returns {ItemHandler} `this` for chaining.
         */
        me.listen = function () {
                me.listening = true;
                return me;
        };

        /**
         * Replace the options list of a select control without unmounting it.
         * @function updateOptions
         * @memberof ItemHandler#
         * @param {Array|object} newOptions - New options array or `{ key: label }` map.
         * @returns {ItemHandler} `this` for chaining.
         */
        me.updateOptions = function (newOptions) {
                if (updateOptionsRef && typeof updateOptionsRef.current === 'function') {
                        updateOptionsRef.current(me.tabIndex, me.itemIndex, newOptions);
                } else {
                        console.warn('updateOptions handler is not available for this control');
                }
                return me;
        };
}

export { ItemHandler };
