import { easing, easingInverse } from './mappings';

export const sync = (itemHandlersRef, pendingCallbackDispatchesRef) => (setState) => {
	setState((prevState) => {
		const newState = { ...prevState };
		let changed = false;

		Object.values(itemHandlersRef.current).forEach((handler) => {
			if (!handler.listening) return;
			const item = newState.tabs[handler.tabIndex].items[handler.itemIndex];

			if (item.object && item.propertyName) {
				if (item.propertyName in item.object) {
					const externalValue = item.object[item.propertyName];

					switch (item.type) {
						case 'slider': {
							const clamped = Math.max(Math.min(externalValue, item.max), item.min);
							if (item.out !== clamped) {
								const power = item.easing ?? 1;
								const res = easingInverse(clamped, item.min, item.max, power);
								//const res = mappings[item.mode].in(clamped, item.min, item.max);
								item.out = clamped;
								item.outTemp = clamped;
								item.in = res;
								item.inTarget = res;
								changed = true;

								pendingCallbackDispatchesRef.current.push({
									callback: itemHandlersRef.current[handler.itemIndex].dispatchOnChange,
									value: clamped,
								});
							}
							break;
						}
                                                case 'select': {
                                                        if (item.value !== externalValue) {
                                                                item.value = externalValue;
                                                                changed = true;

                                                                pendingCallbackDispatchesRef.current.push({
                                                                        callback: itemHandlersRef.current[handler.itemIndex].dispatchOnChange,
                                                                        value: externalValue,
                                                                });
                                                        }
                                                        break;
                                                }
                                                case 'treeList': {
                                                        const arraysEqual = (a, b) =>
                                                                Array.isArray(a) &&
                                                                Array.isArray(b) &&
                                                                a.length === b.length &&
                                                                a.every((v, i) => v === b[i]);
                                                        if (!arraysEqual(item.value, externalValue)) {
                                                                item.value = externalValue;
                                                                changed = true;

                                                                pendingCallbackDispatchesRef.current.push({
                                                                        callback: itemHandlersRef.current[handler.itemIndex].dispatchOnChange,
                                                                        value: externalValue,
                                                                });
                                                        }
                                                        break;
                                                }
                                                case 'switch': {
                                                        const boolVal = !!externalValue;
                                                        if (item.value !== boolVal) {
                                                                item.value = boolVal;
                                                                changed = true;

								pendingCallbackDispatchesRef.current.push({
									callback: itemHandlersRef.current[handler.itemIndex].dispatchOnChange,
									value: boolVal,
								});
							}
							break;
						}
						default:
							break;
					}
				} else {
					console.warn(`Property '${item.propertyName}' does not exist on object`);
				}
			}
		});

		return changed ? newState : prevState;
	});
};
