import React, { useState, useRef } from 'react';
import PropTypes from 'prop-types';
//import { updateIn } from '../reducers/slidersReducers';
import Row from './row';

const ENABLE_TWEEN = false;

// Número de divisiones verticales del fondo del slider
const TRACK_TICKS = 10;
const TICK_COLOR = 'rgba(255, 255, 255, 0.22)';

/**
 * Genera el background-image (linear-gradient) con las divisiones verticales
 * del fondo del slider. Según el easing las marcas se acumulan hacia un lado:
 *  - 'easein'  -> acumuladas a la izquierda (posición = t²)
 *  - 'easeout' -> acumuladas a la derecha   (posición = 1 - (1 - t)²)
 *  - 'linear'  -> espaciado uniforme
 * Reemplaza el gradiente amarillo y las imágenes de /img/.
 */
const buildTrackImage = (mode) => {
	const stops = ['transparent 0'];
	for (let i = 1; i < TRACK_TICKS; i++) {
		const t = i / TRACK_TICKS;
		let p;
		if (mode === 'easein') p = t * t * t;
		else if (mode === 'easeout') p = 1 - (1 - t) * (1 - t) * (1 - t);
		else p = t;
		const pos = (p * 100).toFixed(3);
		stops.push(
			`transparent calc(${pos}% - 0.75px)`,
			`${TICK_COLOR} calc(${pos}% - 0.75px)`,
			`${TICK_COLOR} calc(${pos}% + 0.75px)`,
			`transparent calc(${pos}% + 0.75px)`
		);
	}
	stops.push('transparent 100%');
	return `linear-gradient(to right, ${stops.join(', ')})`;
};

const Slider = (props) => {
	const {
		tabIndex,
		itemIndex,
		label = '',
		step,
		easing,
		min,
		max,
		in: inValue, // renombra in (de props) por inValue para evitar conflictos con el estado
		inTarget,
		out,
		tween = false,
		tweening = false,
		toggleTween,
		updateIn,
		updateOutTemp,
		confirmOut,
		onCommit,
		focused = false,
	} = props;

	const [focus, setFocus] = useState(false);
	const [inputDisplay, setInputDisplay] = useState('');
	const initialValueRef = useRef(null);
	const confirmedRef = useRef(false);

	// Determinar el número de decimales basado en el step
	const decimals = Number.isInteger(step) ? 0 : 3;

	const onChangeRange = (e) => {
		updateIn(tabIndex, itemIndex, parseFloat(e.target.value));
	};

	const onPointerUpRange = (e) => {
		onCommit?.(tabIndex, itemIndex, parseFloat(e.target.value));
	};

	const onChangeInput = (e) => {
		const raw = e.target.value;
		setInputDisplay(raw);
		// Only propagate to state when we have a valid number (not a partial like "1." or "-")
		const parsed = parseFloat(raw);
		if (!isNaN(parsed)) {
			updateOutTemp(tabIndex, itemIndex, parsed);
		}
	};

	const onBlurInput = () => {
		if (!confirmedRef.current) {
			updateOutTemp(tabIndex, itemIndex, initialValueRef.current);
		}
		confirmedRef.current = false;
		setFocus(false);
	};

	const onFocusInput = () => {
		initialValueRef.current = out;
		const formatted = Number(parseFloat(out).toFixed(4));
		updateOutTemp(tabIndex, itemIndex, formatted);
		setInputDisplay(String(formatted));
		setFocus(true);
	};

	const onChangeCheckbox = () => {
		toggleTween(tabIndex, itemIndex);
	};

	const onKeyDown = (e) => {
		if (e.key === 'Enter') {
			confirmedRef.current = true;
			confirmOut(tabIndex, itemIndex);
			e.target.blur();
		} else if (e.key === 'Escape') {
			updateOutTemp(tabIndex, itemIndex, initialValueRef.current);
			setInputDisplay(String(initialValueRef.current));
			confirmedRef.current = false;
			e.target.blur();
		}
	};

	// Determinar clases y valores a mostrar
	let checked = '';
	let value = inValue;
	let className = '';
	let tweenClass = tweening ? 'tweening' : '';

	if (tween) {
		checked = 'checked';
		value = inTarget;
	}

	// Determinar el modo de easing para el fondo del slider
	let easingMode = 'linear';
	if (easing) {
		if (easing < 1) easingMode = 'easeout';
		else if (easing > 1) easingMode = 'easein';
	}
	className = easingMode === 'linear' ? '' : easingMode;
	const trackImage = buildTrackImage(easingMode);

	// Determinar step para el input range
	const rangeStep = step || 'any';

	// Checkbox para tween (o espacio si no hay step)
	let checkbox = null;

	if (ENABLE_TWEEN) {
		checkbox = <div className="spacer">&nbsp;</div>;

		// Solo mostrar checkbox si no tiene step
		if (!step) {
			checkbox = (
				<label className="checkboxContainer">
					<input type="checkbox" onChange={onChangeCheckbox} checked={checked} />
					<span className="checkmark"></span>
				</label>
			);
		}
	}

	// Formatear el valor numérico
	const outValue = focus ? inputDisplay : out.toFixed(decimals);

	return (
		<Row label={label} class="sliderControl" focused={focused}>
			<div className={`col col-md-7 first ${tweenClass}`}>
				<input
					type="range"
					className={`range ${className}`}
					style={{ backgroundImage: trackImage }}
					min={min}
					max={max}
					value={value}
					onChange={onChangeRange}
					onPointerUp={onPointerUpRange}
					step={rangeStep}
					onKeyDown={onKeyDown}
				/>
				{checkbox}
			</div>
			<div className={`col col-md-2 last ${tweenClass}`}>
				<input
					type="text"
					className="form-control-plaintext numero"
					value={outValue}
					size="4"
					maxLength="4"
					onChange={onChangeInput}
					onBlur={onBlurInput}
					onKeyDown={onKeyDown}
					onFocus={onFocusInput}
				/>
			</div>
		</Row>
	);
};

Slider.propTypes = {
	tabIndex: PropTypes.string.isRequired,
	itemIndex: PropTypes.string.isRequired,
	label: PropTypes.string,
	easing: PropTypes.number,
	//mode: PropTypes.oneOf(['lineal', 'easein', 'easeout']).isRequired,
	in: PropTypes.number.isRequired,
	step: PropTypes.number,
	inTarget: PropTypes.number.isRequired,
	out: PropTypes.number.isRequired,
	min: PropTypes.number.isRequired,
	max: PropTypes.number.isRequired,
	tween: PropTypes.bool,
	tweening: PropTypes.bool,
	toggleTween: PropTypes.func.isRequired,
	updateIn: PropTypes.func.isRequired,
	updateOutTemp: PropTypes.func.isRequired,
	confirmOut: PropTypes.func.isRequired,
	onCommit: PropTypes.func,
	focused: PropTypes.bool,
};

// Removed defaultProps in favor of default parameters

export default Slider;
