import { easing, easingInverse } from '../functions/mappings';

export const getControlInitialState = (item) => {
	let res = {};

	switch (item.type) {
		case 'slider':
			if (!item.hasOwnProperty('min')) item.min = 0;
			if (!item.hasOwnProperty('max')) item.max = 1;

			// si hay un valor inicial (initialValue) se refiere al valor de salida del control
			// por ende debo calcular el valor del cursor en el slider.
			// si el modo es lineal es el mismo pero sino la posicion del cursor se calcula
			// usando el valor de salida de mappings como entrada y se busca su valor de cursor

			if (item.hasOwnProperty('initialValue') && !isNaN(item.initialValue)) {
				// primero calculo el out
				res.out = Math.max(item.min, Math.min(item.max, item.initialValue));
				// con ese dato calculo el in

				const power = item.easing ?? 1;
				res.in = easingInverse(res.out, item.min, item.max, power);
				//res.in = mappings[item.mode].in(res.out, item.min, item.max);
			} else {
				// el valor inicial es res.min ya que no hay initialValue
				const power = item.easing ?? 1;
				res.in = easingInverse(item.min, item.min, item.max, power);
				//res.in = mappings[item.mode].in(item.min, item.min, item.max);
				res.out = item.min;
			}

			res.inTarget = res.in;
			res.outTemp = res.out;

			res.tween = false;
			res.tweening = false;
			res.threshold = 0.001;

			break;
		case 'select':
			if (!item.hasOwnProperty('options')) {
				item.options = ['opcion1', 'opcion2'];
				res.value = item.options[0];
			} else {
				if (Array.isArray(item.options)) {
					res.value = item.options[0];
				} else {
					res.value = Object.keys(item.options)[0];
				}
			}

			if (item.hasOwnProperty('initialValue')) {
				if (Array.isArray(item.options)) {
					if (item.options.indexOf(item.initialValue) !== -1) {
						res.value = item.initialValue;
					}
				} else {
					if (Object.keys(item.options).indexOf(item.initialValue) !== -1) {
						res.value = item.initialValue;
					}
				}
			}
			break;
		case 'treeList': {
			const getFirstPath = (node) => {
				const path = [];
				let current = node;
				while (current) {
					if (Array.isArray(current)) {
						if (current.length) path.push(current[0]);
						break;
					} else {
						const keys = Object.keys(current);
						if (!keys.length) break;
						path.push(keys[0]);
						current = current[keys[0]];
					}
				}
				return path;
			};
			const isValidPath = (node, path) => {
				let current = node;
				for (let i = 0; i < path.length; i++) {
					if (Array.isArray(current)) {
						return i === path.length - 1 && current.indexOf(path[i]) !== -1;
					} else if (current && Object.prototype.hasOwnProperty.call(current, path[i])) {
						current = current[path[i]];
					} else {
						return false;
					}
				}
				return Array.isArray(current);
			};
			const defaultPath = getFirstPath(item.tree);
			res.value =
				Array.isArray(item.initialValue) && isValidPath(item.tree, item.initialValue)
					? item.initialValue
					: defaultPath;
			break;
		}
		case 'switch':
			res.value = item.hasOwnProperty('initialValue') ? item.initialValue : false;
			break;
		case 'button':
			// Rows of buttons keep track of an internal focus index for
			// navigation purposes. Default to first button.
			res.focusedButtonIndex = 0;
			break;
		case 'folder':
			// Folders group child controls. `collapsed` is the open/closed state
			// (default open). `collapsible` may be undefined here; it is resolved
			// against the menu-wide `collapsibleFolders` flag when rendering.
			res.collapsed = item.hasOwnProperty('collapsed')
				? !!item.collapsed
				: item.expanded === false;
			break;
	}

	return { initialState: res };
};
