/** Whether an item can receive focus-navigation focus. */
export function isFocusNavigableItem(item) {
	return !!item && !item.hidden && !item.disabled && item.type !== 'separator';
}

/** Item keys in the same stable order used by focus navigation. */
export function getFocusNavigableKeys(items = {}) {
	return Object.keys(items).filter((key) => isFocusNavigableItem(items[key]));
}
