import { useCallback } from 'react';
import { easing, easingInverse } from '../functions/mappings';

/**
 * @description Custom hook to handle user interactions with menu items.
 * @param emitMenuEventRef - ref to the emitMenuEvent function from maincontainer (optional, for canvas renderer events)
 */
export const useItemHandlers = (setState, state, updateDataSource, startTimer, emitMenuEventRef, signalStructuralChange) => {
	// Reducers para sliders
	/**
	 * @description Updates the input value of a slider.
	 */
	const updateIn = useCallback(
		(tabIndex, itemIndex, value, options = {}) => {
			const currentItem = state.tabs[tabIndex]?.items[itemIndex];
			if (!currentItem) return;

			const clampedValue = Math.max(Math.min(value, currentItem.max), currentItem.min);
			const isDirectUpdate = !currentItem.tween || options.direct;
			const outValue = isDirectUpdate
				? easing(clampedValue, currentItem.min, currentItem.max, currentItem.easing ?? 1)
				: null;

			setState((prevState) => {
				const newState = { ...prevState };
				const itemSt = newState.tabs[tabIndex].items[itemIndex];

				if (!itemSt.tween || options.direct) {
					itemSt.in = clampedValue;
					itemSt.inTarget = clampedValue;
					itemSt.out = outValue;
					itemSt.outTemp = outValue;

					updateDataSource(tabIndex, itemIndex, itemSt.out);
				} else {
					itemSt.inTarget = clampedValue;
					itemSt.tweening = true;
					startTimer();
				}

				return newState;
			});

			// Emit from the input call itself instead of relying on React to execute the
			// state updater synchronously. Continuous focus/joystick adjustments run in
			// requestAnimationFrame and React may batch those updates until the gesture
			// ends; the canvas still needs one live patch for every visible value change.
			if (outValue !== null) {
				emitMenuEventRef?.current?.({
					type: 'controlChange',
					tabId: tabIndex,
					itemId: itemIndex,
					itemType: 'slider',
					value: outValue,
					phase: 'change',
					commit: false,
					forceImmediate: options.forceImmediate === true,
					statePatch: { value: outValue },
				});
			}
		},
		[state.tabs, updateDataSource, startTimer, setState, emitMenuEventRef]
	);

	/**
	 * @description Commits the slider value after pointer release (drag end).
	 * Computes the eased output value from the raw range position and emits controlCommit.
	 */
	const commitSlider = useCallback(
		(tabIndex, itemIndex, rawValue) => {
			const item = state.tabs[tabIndex]?.items[itemIndex];
			if (!item) return;
			const clampedValue = Math.max(Math.min(rawValue, item.max), item.min);
			const power = item.easing ?? 1;
			const outValue = easing(clampedValue, item.min, item.max, power);
			emitMenuEventRef?.current?.({
				type: 'controlCommit',
				tabId: tabIndex,
				itemId: itemIndex,
				itemType: 'slider',
				value: outValue,
				phase: 'commit',
				commit: true,
				statePatch: { value: outValue },
			});
		},
		[state.tabs, emitMenuEventRef]
	);

	/**
	 * @description Confirms the output value of a slider after user interaction.
	 */
	const confirmOut = useCallback(
		(tabIndex, itemIndex) => {
			const item = state.tabs[tabIndex]?.items[itemIndex];
			if (!item) return;
			const committedValue = Math.max(Math.min(item.max, item.outTemp ?? item.out), item.min);

			setState((prevState) => {
				const newState = { ...prevState };
				const itemSt = newState.tabs[tabIndex].items[itemIndex];
				const v = prevState.tabs[tabIndex].items[itemIndex];

				const value = Math.max(Math.min(v.max, itemSt.outTemp), v.min);

				newState.tweening = false;

                                const power = v.easing ?? 1;
                                const res = easingInverse(value, v.min, v.max, power);
				//const res = mappings[v.mode].in(value, v.min, v.max);
				itemSt.out = value;
				itemSt.outTemp = value;
				itemSt.in = res;
				itemSt.inTarget = res;

				updateDataSource(tabIndex, itemIndex, itemSt.out);

				return newState;
			});

			emitMenuEventRef?.current?.({
				type: 'controlCommit',
				tabId: tabIndex,
				itemId: itemIndex,
				itemType: 'slider',
				value: committedValue,
				phase: 'commit',
				commit: true,
				statePatch: { value: committedValue },
			});
		},
		[updateDataSource, setState, state.tabs, emitMenuEventRef]
	);

	/**
	 * @description Temporarily updates the output value of a slider for display purposes.
	 */
	const updateOutTemp = useCallback(
		(tabIndex, itemIndex, value) => {
			setState((prevState) => {
				const newState = { ...prevState };
				if (!isNaN(value)) {
					newState.tabs[tabIndex].items[itemIndex].outTemp = Number(value);
				}
				return newState;
			});
		},
		[setState]
	);

	/**
	 * @description Toggles the tweening animation for a slider.
	 */
	const toggleTween = useCallback(
		(tabIndex, itemIndex) => {
			setState((prevState) => {
				const newState = { ...prevState };
				newState.tabs[tabIndex].items[itemIndex].tween = !newState.tabs[tabIndex].items[itemIndex].tween;
				return newState;
			});
		},
		[setState]
	);

	// Reducers para selects
	/**
	 * @description Updates the value of a select control.
	 */
        const updateSelectValue = useCallback(
                (tabIndex, itemIndex, value) => {
                        const itemType = state.tabs[tabIndex]?.items[itemIndex]?.type ?? 'select';
                        setState((prevState) => {
				const tab = prevState.tabs[tabIndex];
				const item = tab?.items[itemIndex];
				if (!item) return prevState;
				return {
					...prevState,
					tabs: {
						...prevState.tabs,
						[tabIndex]: {
							...tab,
							items: { ...tab.items, [itemIndex]: { ...item, value } },
						},
					},
				};
                        });
			updateDataSource(tabIndex, itemIndex, value);
                        emitMenuEventRef?.current?.({
                                type: 'controlCommit',
                                tabId: tabIndex,
                                itemId: itemIndex,
                                itemType,
                                value,
                                phase: 'commit',
                                commit: true,
                                statePatch: { value },
                        });
                },
                [updateDataSource, setState, state.tabs, emitMenuEventRef]
        );

        /**
         * @description Updates the list of options of a select control.
         */
        const updateSelectOptions = useCallback(
                (tabIndex, itemIndex, newOptions) => {
                        setState((prevState) => {
                                const newState = { ...prevState };
                                const item = newState.tabs?.[tabIndex]?.items?.[itemIndex];

                                if (!item) {
                                        return prevState;
                                }

                                if (item.type !== 'select') {
                                        return prevState;
                                }

                                const normalizedOptions = Array.isArray(newOptions)
                                        ? [...newOptions]
                                        : newOptions && typeof newOptions === 'object'
                                        ? { ...newOptions }
                                        : [];

                                item.options = normalizedOptions;

                                const optionKeys = Array.isArray(item.options)
                                        ? item.options
                                        : Object.keys(item.options);

                                if (!optionKeys.length) {
                                        return newState;
                                }

                                if (!optionKeys.includes(item.value)) {
                                        const nextValue = optionKeys[0];
                                        item.value = nextValue;

                                        if (nextValue !== undefined) {
                                                updateDataSource(tabIndex, itemIndex, nextValue);
                                        }
                                }

                                return newState;
                        });
                },
                [setState, updateDataSource]
        );

        /**
         * @description Cycles through the options of a select control.
         */
        const cycleValue = useCallback(
                (tabIndex, itemIndex, direction) => {
                        const item = state.tabs[tabIndex]?.items[itemIndex];
                        if (!item) return;

                        const options = Array.isArray(item.options)
                                ? item.options
                                : Object.keys(item.options || {});

                        if (!options.length) return;

                        let idx = options.indexOf(item.value);
                        if (idx === -1) idx = 0;

                        if (direction === 'next') {
                                idx = (idx + 1) % options.length;
                        } else {
                                idx = (idx - 1 + options.length) % options.length;
                        }

                        const nextValue = options[idx];

                        setState((prevState) => {
                                const newState = { ...prevState };
                                newState.tabs[tabIndex].items[itemIndex].value = nextValue;
                                updateDataSource(tabIndex, itemIndex, nextValue);
                                return newState;
                        });

                        emitMenuEventRef?.current?.({
                                type: 'controlCommit',
                                tabId: tabIndex,
                                itemId: itemIndex,
                                itemType: 'select',
                                value: nextValue,
                                phase: 'commit',
                                commit: true,
                                statePatch: { value: nextValue },
                        });
                },
                [state.tabs, updateDataSource, setState, emitMenuEventRef]
        );

	// Reducers para switches
	/**
	 * @description Updates the value of a switch control.
	 */
	const updateSwitchValue = useCallback(
		(tabIndex, itemIndex) => {
			const newValue = !(state.tabs[tabIndex]?.items[itemIndex]?.value ?? false);
			setState((prevState) => {
				const newState = { ...prevState };
				newState.tabs[tabIndex].items[itemIndex].value = newValue;

				updateDataSource(tabIndex, itemIndex, newValue);

				return newState;
			});
			emitMenuEventRef?.current?.({
				type: 'controlCommit',
				tabId: tabIndex,
				itemId: itemIndex,
				itemType: 'switch',
				value: newValue,
				phase: 'commit',
				commit: true,
				statePatch: { value: newValue },
			});
		},
		[updateDataSource, setState, state.tabs, emitMenuEventRef]
	);

	// Reducers para botones
	/**
	 * @description Calls the action associated with a button.
	 * @param tabIndex Index of the tab containing the button.
	 * @param itemIndex Index of the button item.
	 * @param idx Index of the button action.
	 * @param label Label of the button action.
	 */
	const callButtonAction = useCallback(
		(tabIndex, itemIndex, idx, label) => {
			const item = state.tabs[tabIndex].items[itemIndex];

			if (item.action && typeof item.action === 'function') {
				if (Array.isArray(item.label) || Array.isArray(item.buttons)) {
					item.action(idx, label);
				} else {
					item.action();
				}
			}

			emitMenuEventRef?.current?.({
				type: 'controlCommit',
				tabId: tabIndex,
				itemId: itemIndex,
				itemType: 'button',
				value: idx,
				phase: 'commit',
				commit: true,
				statePatch: { activeButtonIndex: idx, activeButtonLabel: label },
			});
		},
		[state.tabs, emitMenuEventRef]
	);

	// Reducers para carpetas (folders)
	/**
	 * @description Toggles a folder's collapsed (open/closed) state. Because the
	 * collapse changes the total height of the tab, this triggers a structural
	 * change so the canvas renderer recomputes its layout and resizes. No-op when
	 * the folder is not collapsible.
	 */
	const toggleFolder = useCallback(
		(tabIndex, itemIndex) => {
			const item = state.tabs[tabIndex]?.items[itemIndex];
			if (!item || item.type !== 'folder') return;
			const collapsible = item.collapsible ?? state.collapsibleFolders ?? true;
			if (!collapsible) return;

			setState((prevState) => {
				const newState = { ...prevState };
				const it = newState.tabs[tabIndex].items[itemIndex];
				it.collapsed = !it.collapsed;
				return newState;
			});

			// Height of the active tab changed → emit structureChange (rebuilds the
			// snapshot, recomputes auto-size/layout and resizes the canvas).
			signalStructuralChange?.();
		},
		[state.tabs, state.collapsibleFolders, setState, signalStructuralChange]
	);

        return {
                updateIn,
                confirmOut,
                updateOutTemp,
                toggleTween,
                commitSlider,
                updateSelectValue,
                updateSelectOptions,
                cycleValue,
                updateSwitchValue,
                callButtonAction,
                toggleFolder,
        };
};
