/**
 * Returns the items of a tab in display order: each top-level item in insertion
 * order, with every folder immediately followed by its child items (those whose
 * `folderId` points to that folder). Used so both renderers can iterate a flat,
 * already-grouped list while the underlying state stays a flat map.
 *
 * @param {object} itemsMap - The tab's `items` map ({ i0: {...}, i1: {...} }).
 * @returns {Array<[string, object]>} Ordered [itemId, item] entries.
 */
export function orderItemsForDisplay(itemsMap) {
	const entries = Object.entries(itemsMap || {});
	const childrenByFolder = {};
	for (const [id, it] of entries) {
		if (it.folderId) {
			if (!childrenByFolder[it.folderId]) childrenByFolder[it.folderId] = [];
			childrenByFolder[it.folderId].push([id, it]);
		}
	}
	const ordered = [];
	for (const [id, it] of entries) {
		if (it.folderId) continue; // children are emitted right after their folder
		ordered.push([id, it]);
		if (it.type === 'folder' && childrenByFolder[id]) {
			ordered.push(...childrenByFolder[id]);
		}
	}
	// Defensive: children whose folder no longer exists still get rendered.
	for (const [fid, kids] of Object.entries(childrenByFolder)) {
		if (!itemsMap[fid]) ordered.push(...kids);
	}
	return ordered;
}
