import React from 'react';
import PropTypes from 'prop-types';

const Row = ({ label, children, class: className = '', focused = false }) => (
        <div className={`form-row row ${className} ${focused ? 'focused' : ''}`}>
                <div className="col col-md-3 text-right">{label}</div>
                {children}
        </div>
);

Row.propTypes = {
        label: PropTypes.node,
        class: PropTypes.string,
        focused: PropTypes.bool,
        children: PropTypes.node,
};

export default Row;

