/**
 * @class FolderHandler
 * @classdesc Handle returned by `tab.addFolder()`. Use it to add or remove items
 * inside the folder after the menu has been mounted. Symmetric to {@link TabHandler}:
 * a folder visually groups a set of controls inside a tab and (optionally) can be
 * collapsed/expanded by clicking its header.
 *
 * @example
 * const tab = menu.addTab('Settings', 'fa-cog');
 * const folder = tab.addFolder('Advanced');
 *
 * // Same signatures as tab.addItem:
 * folder.addItem({ type: 'slider', label: 'Detail', min: 0, max: 10, step: 1 });
 *
 * const obj = { speed: 0.5 };
 * folder.addItem(obj, 'speed', { type: 'slider', label: 'Speed', min: 0, max: 1 });
 */
function FolderHandler(tabIndex, folderId, addFn, removeFn, folderItemHandler) {
	let me = this;

	/**
	 * Id of this folder's own item within the tab (e.g. `'i3'`).
	 * @type {string}
	 */
	me.folderId = folderId;

	/**
	 * Index of the tab this folder belongs to.
	 * @type {string}
	 */
	me.tabIndex = tabIndex;

	/**
	 * The ItemHandler of the folder header itself (for `.onChange`, removal, etc.).
	 * @type {ItemHandler}
	 */
	me.handler = folderItemHandler;

	/**
	 * Add a control item to this folder. Same signatures as `tab.addItem`:
	 *
	 * **Signature 1 – config object:** `folder.addItem({ type, label, ... })`
	 *
	 * **Signature 2 – bound object property:** `folder.addItem(object, propertyName, { type, label, ... })`
	 *
	 * @function addItem
	 * @memberof FolderHandler#
	 * @param {object|any} arg1 - Item config object **or** the object to bind.
	 * @param {string}     [arg2] - Property name on `arg1` (signature 2 only).
	 * @param {object}     [arg3] - Item config overrides (signature 2 only).
	 * @returns {ItemHandler}
	 */
	me.addItem = function (arg1, arg2, arg3) {
		let params;

		if (arguments.length === 1) {
			params = arg1;
		} else {
			params = arg3 || {};
			params.object = arg1;
			params.propertyName = arg2;
			if (arg1 && typeof arg1 === 'object' && arg2 in arg1) {
				params.initialValue = arg1[arg2];
			} else if (arg3 && arg3.value !== undefined) {
				params.initialValue = arg3.initialValue;
			}
		}

		if (params.type === 'button' && Array.isArray(params.label)) {
			params.buttons = params.label;
			params.label = '';
		}

		// Tag the item so the renderers group it under this folder.
		params.folderId = folderId;

		return addFn(tabIndex, params);
	};

	/**
	 * Remove an item from this folder.
	 * @function removeItem
	 * @memberof FolderHandler#
	 * @param {ItemHandler} item - The handler returned by `addItem`.
	 */
	me.removeItem = function (item) {
		return removeFn(item);
	};
}

export { FolderHandler };
