const decimalPlaces = (value) => {
	const text = String(value).toLowerCase();
	if (text.includes('e-')) return Number(text.split('e-')[1]);
	return (text.split('.')[1] || '').length;
};

/** Quantize a raw slider value against min while avoiding visible FP noise. */
export function quantizeSliderValue(value, min, max, step) {
	const clamped = Math.max(min, Math.min(max, value));
	if (!Number.isFinite(step) || step <= 0) return clamped;

	const precision = Math.min(12, Math.max(decimalPlaces(min), decimalPlaces(max), decimalPlaces(step)) + 2);
	const steps = Math.round((clamped - min) / step);
	const quantized = min + steps * step;
	return Number(Math.max(min, Math.min(max, quantized)).toFixed(precision));
}

/** Advance a continuous adjustment session and retain its unquantized residue. */
export function advanceSliderAdjustment(session, normalizedDelta) {
	const range = session.max - session.min;
	session.accumulatedValue = Math.max(
		session.min,
		Math.min(session.max, session.accumulatedValue + normalizedDelta * range)
	);
	const value = quantizeSliderValue(session.accumulatedValue, session.min, session.max, session.step);
	const changed = !Object.is(value, session.visibleValue);
	if (changed) session.visibleValue = value;
	return { changed, value };
}
