import { useState, useEffect, useCallback, useRef } from 'react';
import { advanceSliderAdjustment } from '../utils/focusedValueAdjustment';
import { getFocusNavigableKeys } from '../utils/focusableItems';
import { completeTreePath, moveTreePath, treePathsEqual } from '../utils/treePath';

// Auto-repeat timing for held directions (e.g. holding "right" over a slider).
const REPEAT_DELAY = 300; // ms before the auto-repeat kicks in
const REPEAT_INTERVAL = 90; // ms between repeats while held

/**
 * Hook in charge of handling focus based navigation for the menu.
 * All the logic is kept here to keep Maincontainer as lean as possible.
 *
 * @param {object}   state    Menu state.
 * @param {Function} setState Menu state setter.
 * @param {object}   handlers Item mutation handlers.
 * @param {boolean}  enabled  Whether focus navigation is active. When false the
 *                            hook is inert: `focus` is null and every move/activate
 *                            is a no-op. Set at construction time via createMenu.
 */
export const useFocusNavigation = (state, setState, handlers, enabled = false) => {
	const { updateIn, commitSlider, updateSelectValue, updateSwitchValue, callButtonAction } = handlers;

	// The feature may be enabled without showing a cursor. A navigation command
	// explicitly activates it at the current tab; pointer interaction resets it.
	const [focus, setFocus] = useState(null);
	const stateRef = useRef(state);
	const focusRef = useRef(focus);
	const adjustmentRef = useRef(null);
	const heldRef = useRef({});
	stateRef.current = state;
	focusRef.current = focus;

	// keep focus tab in sync with active tab
	useEffect(() => {
		if (!enabled) return;
		setFocus((prev) => (prev ? { ...prev, tabIndex: state.currentTab } : null));
	}, [state.currentTab, enabled]);

	// helpers ---------------------------------------------------------------
	const getTabKeys = () => Object.keys(state.tabs);

	const getVisibleControlKeys = (tabIndex) => {
		const items = state.tabs[tabIndex]?.items || {};
		return getFocusNavigableKeys(items);
	};

	const getItemAt = (tabIndex, controlIndex) => {
		const keys = getVisibleControlKeys(tabIndex);
		const key = keys[controlIndex];
		if (!key) return { key: undefined, item: undefined };
		return { key, item: state.tabs[tabIndex].items[key] };
	};

	const beginFocusedValueAdjustment = useCallback(() => {
		if (!enabled || adjustmentRef.current) return false;
		const currentFocus = focusRef.current;
		if (!currentFocus || currentFocus.area !== 'panel') return false;
		const items = stateRef.current.tabs[currentFocus.tabIndex]?.items || {};
		const visibleKeys = getFocusNavigableKeys(items);
		const itemId = visibleKeys[currentFocus.controlIndex];
		const item = items[itemId];
		if (!item || item.type !== 'slider') return false;

		const min = Number(item.min);
		const max = Number(item.max);
		const value = Number(item.in);
		if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min || !Number.isFinite(value)) return false;

		adjustmentRef.current = {
			tabId: currentFocus.tabIndex,
			itemId,
			min,
			max,
			step: Number(item.step),
			accumulatedValue: Math.max(min, Math.min(max, value)),
			visibleValue: value,
		};
		return true;
	}, [enabled]);

	const adjustFocusedValue = useCallback((normalizedDelta) => {
		const session = adjustmentRef.current;
		if (!session || !Number.isFinite(normalizedDelta)) return false;
		const item = stateRef.current.tabs[session.tabId]?.items[session.itemId];
		if (!item || item.type !== 'slider') {
			adjustmentRef.current = null;
			return false;
		}

		const { changed, value: nextValue } = advanceSliderAdjustment(session, normalizedDelta);
		if (!changed) return false;
		updateIn(session.tabId, session.itemId, nextValue, { direct: true, forceImmediate: true });
		return true;
	}, [updateIn]);

	const endFocusedValueAdjustment = useCallback(() => {
		const session = adjustmentRef.current;
		if (!session) return false;
		adjustmentRef.current = null;
		const item = stateRef.current.tabs[session.tabId]?.items[session.itemId];
		if (item?.type === 'slider') commitSlider?.(session.tabId, session.itemId, session.visibleValue);
		return true;
	}, [commitSlider]);

	const activateFocusNavigation = useCallback(() => {
		if (!enabled) return null;
		const currentFocus = focusRef.current;
		if (currentFocus) return currentFocus;
		const newFocus = { area: 'tabs', tabIndex: stateRef.current.currentTab };
		focusRef.current = newFocus;
		setFocus(newFocus);
		return newFocus;
	}, [enabled]);

	const deactivateFocusNavigation = useCallback(() => {
		Object.values(heldRef.current).forEach((held) => {
			if (held?.timeout) clearTimeout(held.timeout);
			if (held?.interval) clearInterval(held.interval);
		});
		heldRef.current = {};

		const session = adjustmentRef.current;
		adjustmentRef.current = null;
		if (session) {
			const item = stateRef.current.tabs[session.tabId]?.items[session.itemId];
			if (item?.type === 'slider') commitSlider?.(session.tabId, session.itemId, session.visibleValue);
		}

		focusRef.current = null;
		setFocus(null);
		return { deactivated: true };
	}, [commitSlider]);

        const getDefaultSubIndex = (item) => {
                if (!item) return undefined;
                if (item.type === 'button') {
                        return item.focusedButtonIndex || 0;
                }
                return undefined;
        };

        const getDefaultTreeFocus = (item) => {
                if (!item || item.type !== 'treeList') return undefined;
		const path = completeTreePath(item.tree, item.value);
                return { level: 0, path };
        };

        // lifecycle -----------------------------------------------------------
        // Keep the focus valid when controls are added/removed or hidden/disabled:
        // clamp the focused row to the last visible control, or fall back to the
        // tabs area when the active tab has no reachable controls.
        useEffect(() => {
                if (!enabled) return;
                setFocus((prev) => {
                        if (!prev || prev.area !== 'panel') return prev;
                        const keys = getVisibleControlKeys(prev.tabIndex);
                        if (!keys.length) return { area: 'tabs', tabIndex: prev.tabIndex };
                        if (prev.controlIndex > keys.length - 1) {
                                const newIndex = keys.length - 1;
                                const { item } = getItemAt(prev.tabIndex, newIndex);
                                return {
                                        area: 'panel',
                                        tabIndex: prev.tabIndex,
                                        controlIndex: newIndex,
                                        subIndex: getDefaultSubIndex(item),
                                        tree: getDefaultTreeFocus(item),
                                };
                        }
                        return prev;
                });
        // eslint-disable-next-line react-hooks/exhaustive-deps
        }, [state.tabs, enabled]);

	// Mouse selection updates the tree value independently of focus navigation.
	// Keep the focus path on that same branch so the focused DOM tree never keeps
	// rendering levels from the previously selected branch.
	const focusedTreeItem = focus?.area === 'panel' ? getItemAt(focus.tabIndex, focus.controlIndex).item : null;
	const focusedTreeValueSignature = focusedTreeItem?.type === 'treeList' ? JSON.stringify(focusedTreeItem.value) : '';
	useEffect(() => {
		if (!enabled || !focusedTreeItem || focusedTreeItem.type !== 'treeList') return;
		const selectedPath = completeTreePath(focusedTreeItem.tree, focusedTreeItem.value);
		setFocus((prev) => {
			if (!prev?.tree || treePathsEqual(prev.tree.path, selectedPath)) return prev;
			return {
				...prev,
				tree: { level: Math.min(prev.tree.level, Math.max(0, selectedPath.length - 1)), path: selectedPath },
			};
		});
	// The serialized path changes only when selection changes, not while the cursor
	// browses an uncommitted option within the same tree.
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [enabled, focusedTreeValueSignature]);

	// movement -------------------------------------------------------------
        const moveUp = useCallback(() => {
                if (!enabled) return { moved: false, focus };
		if (!focusRef.current) return { moved: false, focus: null };
                if (focus.area === 'tabs') return { moved: false, focus };
                const { item } = getItemAt(focus.tabIndex, focus.controlIndex);
                if (item?.type === 'treeList' && focus.tree) {
                        const { level, path } = focus.tree;
			if (level > 0) {
				const newTree = { level: level - 1, path };
				setFocus((prev) => ({ ...prev, tree: newTree }));
				return { moved: true, focus: { ...focus, tree: newTree } };
			}
                }
                const keys = getVisibleControlKeys(focus.tabIndex);
                if (focus.controlIndex <= 0) {
                        const newFocus = { area: 'tabs', tabIndex: focus.tabIndex };
                        setFocus(newFocus);
                        return { moved: true, focus: newFocus };
                }
                const newIndex = focus.controlIndex - 1;
                const { item: prevItem } = getItemAt(focus.tabIndex, newIndex);
                const newFocus = {
                        area: 'panel',
                        tabIndex: focus.tabIndex,
                        controlIndex: newIndex,
                        subIndex: getDefaultSubIndex(prevItem),
                        tree: getDefaultTreeFocus(prevItem),
                };
                setFocus(newFocus);
                return { moved: true, focus: newFocus };
        }, [focus, enabled]);

        const moveDown = useCallback(() => {
                if (!enabled) return { moved: false, focus };
		if (!focusRef.current) {
			const newFocus = activateFocusNavigation();
			return { moved: !!newFocus, activated: !!newFocus, focus: newFocus };
		}
                if (focus.area === 'tabs') {
                        const keys = getVisibleControlKeys(focus.tabIndex);
                        if (!keys.length) return { moved: false, focus };
                        const { item } = getItemAt(focus.tabIndex, 0);
                        const newFocus = {
                                area: 'panel',
                                tabIndex: focus.tabIndex,
                                controlIndex: 0,
                                subIndex: getDefaultSubIndex(item),
                                tree: getDefaultTreeFocus(item),
                        };
                        setFocus(newFocus);
                        return { moved: true, focus: newFocus };
                }
                const { item } = getItemAt(focus.tabIndex, focus.controlIndex);
                if (item?.type === 'treeList' && focus.tree) {
                        const { level, path } = focus.tree;
			const nextLevel = level + 1;
			if (nextLevel < path.length) {
				const newTree = { level: nextLevel, path };
				setFocus((prev) => ({ ...prev, tree: newTree }));
				return { moved: true, focus: { ...focus, tree: newTree } };
			}
                }
                const keys = getVisibleControlKeys(focus.tabIndex);
                if (focus.controlIndex >= keys.length - 1) {
                        return { moved: false, focus };
                }
                const newIndex = focus.controlIndex + 1;
                const { item: nextItem } = getItemAt(focus.tabIndex, newIndex);
                const newFocus = {
                        area: 'panel',
                        tabIndex: focus.tabIndex,
                        controlIndex: newIndex,
                        subIndex: getDefaultSubIndex(nextItem),
                        tree: getDefaultTreeFocus(nextItem),
                };
                setFocus(newFocus);
                return { moved: true, focus: newFocus };
        }, [focus, enabled, activateFocusNavigation]);

	const moveLeft = useCallback(() => {
		if (!enabled) return { moved: false, focus };
		if (!focusRef.current) return { moved: false, focus: null };
		if (focus.area === 'tabs') {
			const tabs = getTabKeys();
			const idx = tabs.indexOf(focus.tabIndex);
			if (idx <= 0) return { moved: false, focus };
			const newTab = tabs[idx - 1];
			setState((prev) => ({ ...prev, currentTab: newTab }));
			const newFocus = { area: 'tabs', tabIndex: newTab };
			setFocus(newFocus);
			return { moved: true, focus: newFocus };
		}
		const { key, item } = getItemAt(focus.tabIndex, focus.controlIndex);
		if (!item) return { moved: false, focus };
		let moved = false;
		switch (item.type) {
			case 'slider': {
				const step = item.step ?? (item.max - item.min) * 0.01;
				const newVal = Math.max(item.in - step, item.min);
				if (newVal !== item.in) {
					updateIn(focus.tabIndex, key, newVal);
					// commit so the canvas (commitOnly mode) reflects the change
					commitSlider?.(focus.tabIndex, key, newVal);
					moved = true;
				}
				break;
			}
			case 'select': {
				const options = Array.isArray(item.options) ? item.options : Object.keys(item.options);
				let idx = options.indexOf(item.value);
				let next = idx - 1;
				if (item.wrap) {
					next = (next + options.length) % options.length;
				} else {
					next = Math.max(0, next);
				}
				if (next !== idx) {
					updateSelectValue(focus.tabIndex, key, options[next]);
					moved = true;
				}
				break;
			}
			case 'button': {
				const buttons = Array.isArray(item.buttons) ? item.buttons : [item.text];
				let idx = item.focusedButtonIndex || 0;
				let next = idx - 1;
				if (item.wrap) {
					next = (next + buttons.length) % buttons.length;
				} else {
					next = Math.max(0, next);
				}
				if (next !== idx) {
					setState((prev) => {
						const ns = { ...prev };
						ns.tabs[focus.tabIndex].items[key].focusedButtonIndex = next;
						return ns;
					});
					moved = true;
					setFocus((prev) => ({ ...prev, subIndex: next }));
				}
				break;
			}
                        case 'switch': {
                                if (item.value) {
                                        updateSwitchValue(focus.tabIndex, key);
                                        moved = true;
                                }
                                break;
                        }
                        case 'treeList': {
                                if (focus.tree) {
                                        const { level, path } = focus.tree;
					const newPath = moveTreePath(item.tree, path, level, 'left');
					if (newPath) {
						updateSelectValue(focus.tabIndex, key, newPath);
						setFocus((prev) => ({ ...prev, tree: { level, path: newPath } }));
						moved = true;
					}
                                }
                                break;
                        }
                        default:
                                break;
                }
                return { moved, focus: { ...focus } };
	}, [focus, state, enabled]);

	const moveRight = useCallback(() => {
		if (!enabled) return { moved: false, focus };
		if (!focusRef.current) return { moved: false, focus: null };
		if (focus.area === 'tabs') {
			const tabs = getTabKeys();
			const idx = tabs.indexOf(focus.tabIndex);
			if (idx === -1 || idx >= tabs.length - 1) return { moved: false, focus };
			const newTab = tabs[idx + 1];
			setState((prev) => ({ ...prev, currentTab: newTab }));
			const newFocus = { area: 'tabs', tabIndex: newTab };
			setFocus(newFocus);
			return { moved: true, focus: newFocus };
		}
		const { key, item } = getItemAt(focus.tabIndex, focus.controlIndex);
		if (!item) return { moved: false, focus };
		let moved = false;
		switch (item.type) {
			case 'slider': {
				const step = item.step ?? (item.max - item.min) * 0.01;
				const newVal = Math.min(item.in + step, item.max);
				if (newVal !== item.in) {
					updateIn(focus.tabIndex, key, newVal);
					// commit so the canvas (commitOnly mode) reflects the change
					commitSlider?.(focus.tabIndex, key, newVal);
					moved = true;
				}
				break;
			}
			case 'select': {
				const options = Array.isArray(item.options) ? item.options : Object.keys(item.options);
				let idx = options.indexOf(item.value);
				let next = idx + 1;
				if (item.wrap) {
					next = (next + options.length) % options.length;
				} else {
					next = Math.min(options.length - 1, next);
				}
				if (next !== idx) {
					updateSelectValue(focus.tabIndex, key, options[next]);
					moved = true;
				}
				break;
			}
			case 'button': {
				const buttons = Array.isArray(item.buttons) ? item.buttons : [item.text];
				let idx = item.focusedButtonIndex || 0;
				let next = idx + 1;
				if (item.wrap) {
					next = next % buttons.length;
				} else {
					next = Math.min(buttons.length - 1, next);
				}
				if (next !== idx) {
					setState((prev) => {
						const ns = { ...prev };
						ns.tabs[focus.tabIndex].items[key].focusedButtonIndex = next;
						return ns;
					});
					moved = true;
					setFocus((prev) => ({ ...prev, subIndex: next }));
				}
				break;
			}
                        case 'switch': {
                                if (!item.value) {
                                        updateSwitchValue(focus.tabIndex, key);
                                        moved = true;
                                }
                                break;
                        }
                        case 'treeList': {
                                if (focus.tree) {
                                        const { level, path } = focus.tree;
					const newPath = moveTreePath(item.tree, path, level, 'right');
					if (newPath) {
						updateSelectValue(focus.tabIndex, key, newPath);
						setFocus((prev) => ({ ...prev, tree: { level, path: newPath } }));
						moved = true;
					}
                                }
                                break;
                        }
                        default:
                                break;
                }
                return { moved, focus: { ...focus } };
	}, [focus, state, enabled]);

	/** Trigger only the button currently targeted inside a focused action row. */
	const clickFocusedButton = useCallback(() => {
		if (!enabled || focus?.area !== 'panel') return { executed: false };
		const { key, item } = getItemAt(focus.tabIndex, focus.controlIndex);
		if (!item || item.type !== 'button') return { executed: false };

		const buttons = Array.isArray(item.buttons) ? item.buttons : [item.text ?? item.label ?? 'execute'];
		if (!buttons.length) return { executed: false };
		const index = Math.max(0, Math.min(focus.subIndex ?? item.focusedButtonIndex ?? 0, buttons.length - 1));
		const button = buttons[index];
		const label = typeof button === 'object' ? button.label ?? '' : button;
		callButtonAction(focus.tabIndex, key, index, label);
		return { executed: true };
	}, [enabled, focus, state, callButtonAction]);

	const activate = useCallback(() => {
		if (!enabled || !focus) return { executed: false };
		if (focus.area === 'panel') {
			const { key, item } = getItemAt(focus.tabIndex, focus.controlIndex);
			if (!item) return { executed: false };
                        switch (item.type) {
				case 'button':
					return clickFocusedButton();
                                case 'switch': {
                                        updateSwitchValue(focus.tabIndex, key);
                                        return { executed: true };
                                }
                                case 'treeList': {
                                        if (focus.tree) {
                                                const { level, path } = focus.tree;
								const newPath = completeTreePath(item.tree, path.slice(0, level + 1));
                                                updateSelectValue(focus.tabIndex, key, newPath);
                                                setFocus((prev) => ({ ...prev, tree: { level, path: newPath } }));
                                                return { executed: true };
                                        }
                                        break;
                                }
                                default:
                                        break;
                        }
                }
                return { executed: false };
	}, [focus, state, clickFocusedButton]);

	// press / release ------------------------------------------------------
	// Hold semantics: instead of one discrete step per call, the host can "press"
	// a direction and keep it held. The action fires once immediately and then
	// auto-repeats while held (until "release"). This lets a held left/right ramp
	// a slider value gradually without spamming clicks. 'activate' fires once and
	// never repeats. Directions: 'up' | 'down' | 'left' | 'right' | 'activate'.

	// Always points to the freshest action closures so timers don't run stale ones.
	const actionsRef = useRef({});
	actionsRef.current = { up: moveUp, down: moveDown, left: moveLeft, right: moveRight, activate };

	const release = useCallback((dir) => {
		const h = heldRef.current[dir];
		if (!h) return;
		if (h.timeout) clearTimeout(h.timeout);
		if (h.interval) clearInterval(h.interval);
		delete heldRef.current[dir];
	}, []);

	const press = useCallback(
		(dir) => {
			if (!enabled) return { moved: false };
			const run = () => actionsRef.current[dir]?.();
			// Immediate action on press.
			const result = run();
			// 'activate' is a one-shot; directions auto-repeat while held.
			if (dir === 'activate') return result;
			// Guard against duplicate presses without a release in between.
			if (heldRef.current[dir]) return result;
			const timeout = setTimeout(() => {
				const interval = setInterval(run, REPEAT_INTERVAL);
				heldRef.current[dir] = { interval };
			}, REPEAT_DELAY);
			heldRef.current[dir] = { timeout };
			return result;
		},
		[enabled]
	);

	// Clear any pending timers on unmount.
	useEffect(() => {
		const held = heldRef.current;
		return () => {
			Object.keys(held).forEach((dir) => {
				if (held[dir]?.timeout) clearTimeout(held[dir].timeout);
				if (held[dir]?.interval) clearInterval(held[dir].interval);
			});
		};
	}, []);

	return {
		focus,
		moveUp,
		moveDown,
		moveLeft,
		moveRight,
		clickFocusedButton,
		activate,
		press,
		release,
		beginFocusedValueAdjustment,
		adjustFocusedValue,
		endFocusedValueAdjustment,
		deactivateFocusNavigation,
	};
};
