export function easing(x, min, max, power) {
	if (power <= 0) throw 'power must be greater than 0';
	if (power == 1) return Math.min(Math.max(x, min), max);
	let n = min + Math.pow((x - min) / (max - min), power) * (max - min);
	return n;
}

export function easingInverse(x, min, max, power) {
	if (power <= 0) throw 'power must be greater than 0';
	if (power == 1) return Math.min(Math.max(x, min), max);
	let n = min + Math.pow((x - min) / (max - min), 1 / power) * (max - min);
	return n;
}
