import React, { useMemo } from 'react';
import PropTypes from 'prop-types';
import Row from './row';
import { completeTreePath } from '../utils/treePath';

const TreeList = ({
        tabIndex,
        itemIndex,
        label = '',
        tree,
        value,
        onChange,
        focused = false,
        focusPath = [],
        focusLevel = -1,
}) => {
        const maxLeafCount = useMemo(() => {
                const countLeaves = (node) => {
                        if (Array.isArray(node)) return node.length;
                        return Object.values(node || {}).reduce((max, child) => Math.max(max, countLeaves(child)), 0);
                };
                return countLeaves(tree);
        }, [tree]);

        const levels = useMemo(() => {
                const result = [];
                const traverse = (node, focusP, selP, level) => {
                        const options = Array.isArray(node) ? node : Object.keys(node);
                        const isLast = Array.isArray(node);
                        const selected = selP[level];
                        result.push({ options, selected, isLast });
                        const nextKey = focusP[level];
                        if (!isLast && nextKey !== undefined && node[nextKey] !== undefined) {
                                traverse(node[nextKey], focusP, selP, level + 1);
                        }
                };
                const pathToFollow = focused ? focusPath : value;
                traverse(tree, pathToFollow, value, 0);
                return result;
        }, [tree, value, focusPath, focused]);

        const handleClick = (levelIdx, option) => {
                const newPath = completeTreePath(tree, [...value.slice(0, levelIdx), option]);
                onChange(tabIndex, itemIndex, newPath);
        };

        const renderLevel = (level, idx) => {
                const isFocusedLevel = focused && focusLevel === idx;
                return (
                        <div key={idx} className={level.isLast ? 'tree-horizontal tree-wrap' : 'tree-horizontal'}>
                                {level.options.map((opt) => (
                                        <div
                                                key={opt}
                                                className={`tree-item ${
                                                        opt === level.selected ? 'selected' : ''
                                                } ${isFocusedLevel && opt === focusPath[idx] ? 'focused' : ''}`}
                                                onClick={() => handleClick(idx, opt)}
                                        >
                                                {opt}
                                        </div>
                                ))}
                        </div>
                );
        };

        return (
                <Row label={label} class="treeList" focused={focused}>
                        <div className="col col-md-9">
                                {levels.map((level, idx) => (
                                        <React.Fragment key={idx}>
                                                {idx > 0 && <hr className="tree-divider" />}
                                                {renderLevel(level, idx)}
                                        </React.Fragment>
                                ))}
                        </div>
                </Row>
        );
};

TreeList.propTypes = {
        tabIndex: PropTypes.string.isRequired,
        itemIndex: PropTypes.string.isRequired,
        label: PropTypes.string,
        tree: PropTypes.oneOfType([PropTypes.object, PropTypes.array]).isRequired,
        value: PropTypes.array.isRequired,
        onChange: PropTypes.func.isRequired,
        focused: PropTypes.bool,
        focusPath: PropTypes.array,
        focusLevel: PropTypes.number,
};

export default TreeList;

