import React, { useCallback } from 'react';
import PropTypes from 'prop-types';

/**
 * Folder header. Renders a clickable bar (when collapsible) with a chevron and the
 * folder label. The folder's child controls are rendered separately by Mainmenu,
 * grouped right after this header.
 */
const Folder = ({ tabIndex, itemIndex, label = '', collapsed = false, collapsible = true, onToggle, focused = false }) => {
	const handleToggle = useCallback(() => {
		if (!collapsible) return;
		onToggle?.(tabIndex, itemIndex);
	}, [collapsible, onToggle, tabIndex, itemIndex]);

	const chevron = collapsible ? (collapsed ? '▸' : '▾') : '';

	return (
		<div className={`form-row row folderControl ${focused ? 'focused' : ''}`}>
			<button
				type="button"
				className={`folder-header col col-md-12 ${collapsible ? 'collapsible' : 'static'} ${
					collapsed ? 'collapsed' : 'open'
				}`}
				onClick={handleToggle}
				disabled={!collapsible}
				aria-expanded={collapsible ? !collapsed : undefined}
			>
				{chevron && <span className="folder-chevron">{chevron}</span>}
				<span className="folder-title">{label}</span>
			</button>
		</div>
	);
};

Folder.propTypes = {
	tabIndex: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
	itemIndex: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
	label: PropTypes.string,
	collapsed: PropTypes.bool,
	collapsible: PropTypes.bool,
	onToggle: PropTypes.func,
	focused: PropTypes.bool,
};

export default React.memo(Folder);
