import { useCallback } from 'react';
import { ItemHandler } from '../extras/itemHandler';
import { TabHandler } from '../extras/tabHandler';
import { getControlInitialState } from '../utils/controlState';

/**
 * @description Custom hook to handle menu actions like adding/removing tabs and items.
 */
export const useMenuActions = (
        setState,
        //addKeyboardHandler,
        itemHandlersRef,
        lastItemIndexRef,
        lastTabIndexRef,
        updateSelectOptionsRef,
        signalStructuralChange
) => {
	/**
	 * @description Adds an item to a specific tab.
	 */
	const addItem = useCallback(
		(tabIndex, item) => {
			const itemIndex = 'i' + lastItemIndexRef.current;

                        const itemHandler = new ItemHandler(tabIndex, itemIndex, updateSelectOptionsRef);
			itemHandlersRef.current[itemIndex] = itemHandler;

			if (item.key || item.keys) {
				//addKeyboardHandler(tabIndex, itemIndex, item);
			}

			lastItemIndexRef.current++;

			setState((prevState) => {
				const newState = { ...prevState };

				const { initialState } = getControlInitialState(item);

				const updatedItem = { ...item, ...initialState };

				if (!newState.tabs[tabIndex].items) {
					newState.tabs[tabIndex].items = {};
				}

				newState.tabs[tabIndex].items[itemIndex] = updatedItem;

				return newState;
			});

			signalStructuralChange();

			return itemHandler;
		},
                [/*addKeyboardHandler,*/ setState, itemHandlersRef, lastItemIndexRef, updateSelectOptionsRef, signalStructuralChange]
        );

	/**
	 * @description Removes an item from a tab.
	 */
	const removeItem = useCallback(
		(item) => {
			setState((prevState) => {
				const newState = { ...prevState };

				delete itemHandlersRef.current[item.itemIndex];
				delete newState.tabs[item.tabIndex].items[item.itemIndex];

				return newState;
			});

			signalStructuralChange();
		},
		[setState, itemHandlersRef, signalStructuralChange]
	);

	/**
	 * @description Adds a new tab to the menu.
	 */
	const addTab = useCallback(
		(title, icon) => {
			const idx = lastTabIndexRef.current;
			lastTabIndexRef.current = idx + 1;

			const tabIndex = 't' + idx;

			setState((prevState) => {
				const newState = { ...prevState };

				if (newState.currentTab === undefined) {
					newState.currentTab = tabIndex;
				}

				newState.tabs[tabIndex] = {
					title: title,
					icon: icon,
					items: {},
				};

				return newState;
			});

			return new TabHandler(tabIndex, addItem, removeItem);
		},
		[addItem, removeItem, setState, lastTabIndexRef]
	);

	/**
	 * @description Removes a tab from the menu.
	 */
	const removeTab = useCallback(
		(tab) => {
			setState((prevState) => {
				const newState = { ...prevState };

				Object.keys(newState.tabs[tab.tabIndex].items).forEach((itemIndex) => {
					delete itemHandlersRef.current[itemIndex];
				});

				delete newState.tabs[tab.tabIndex];

				return newState;
			});
		},
		[setState, itemHandlersRef]
	);

	return { addTab, removeTab };
};
