import React from 'react';

import Row from './row';
import PropTypes from 'prop-types';

const Select = ({ tabIndex, itemIndex, label = '', value, options, onChange, onCycle, focused = false }) => {
	const handleChange = (e) => {
		e.target.blur();
		onChange(tabIndex, itemIndex, e.target.value);
	};

	const handleClickLeft = () => {
		onCycle(tabIndex, itemIndex, 'previous');
	};

	const handleClickRight = () => {
		onCycle(tabIndex, itemIndex, 'next');
	};

	// Generar opciones para el select
	const optionElements = [];

	if (Array.isArray(options)) {
		options.forEach((element) => {
			optionElements.push(
				<option key={element} value={element}>
					{element}
				</option>
			);
		});
	} else {
		for (let k in options) {
			optionElements.push(
				<option key={k} value={k}>
					{options[k]}
				</option>
			);
		}
	}

	return (
		<Row label={label} class="selectItem" focused={focused}>
			<div className="col col-md-7">
				<select className="form-control-sm" onChange={handleChange} value={value}>
					{optionElements}
				</select>
			</div>
			<div className="col col-md-2 text-center">
				<button className="btn btn-secondary btn-sm" onClick={handleClickLeft} aria-label="previous">
					<svg viewBox="0 0 256 512" aria-hidden="true" focusable="false">
						<path d="M192 127.3v257.4c0 17.8-21.5 26.7-34.1 14.1L29.2 270.1c-7.8-7.8-7.8-20.5 0-28.3l128.7-128.7c12.6-12.5 34.1-3.6 34.1 14.2z" />
					</svg>
				</button>
				<button className="btn btn-secondary btn-sm" onClick={handleClickRight} aria-label="next">
					<svg viewBox="0 0 256 512" aria-hidden="true" focusable="false">
						<path d="M64 384.8V127.2c0-17.8 21.5-26.7 34.1-14.1l128.7 128.7c7.8 7.8 7.8 20.5 0 28.3L98.1 398.9c-12.6 12.5-34.1 3.6-34.1-14.1z" />
					</svg>
				</button>
			</div>
		</Row>
	);
};

Select.propTypes = {
	tabIndex: PropTypes.string.isRequired,
	itemIndex: PropTypes.string.isRequired,
	label: PropTypes.string,
	value: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
	options: PropTypes.oneOfType([PropTypes.object, PropTypes.array]).isRequired,
	onChange: PropTypes.func.isRequired,
	onCycle: PropTypes.func.isRequired,
	focused: PropTypes.bool,
};

// Removed defaultProps in favor of default parameters

export default Select;
