/**
 * @class TabHandler
 * @classdesc Handle returned by `menu.addTab()`. Use it to add or remove items
 * from the tab after the menu has been mounted.
 *
 * @example
 * const tab = menu.addTab('Settings', 'fa-cog');
 *
 * // Signature 1 – item config object
 * const vol = tab.addItem({ type: 'slider', label: 'Volume', min: 0, max: 1 });
 *
 * // Signature 2 – bind to an existing object property
 * const obj = { speed: 0.5 };
 * const spd = tab.addItem(obj, 'speed', { type: 'slider', label: 'Speed', min: 0, max: 1 });
 */
import { FolderHandler } from './folderHandler';

function TabHandler(tabIndex, addFn, removeFn) {
	let me = this;

	/**
	 * Zero-based index of this tab within the menu.
	 * @type {number}
	 */
	me.tabIndex = tabIndex;

	/**
	 * Add a control item to this tab.
	 *
	 * **Signature 1 – config object:**
	 * ```js
	 * tab.addItem({ type, label, min, max, ... })
	 * ```
	 *
	 * **Signature 2 – bound object property:**
	 * ```js
	 * tab.addItem(object, propertyName, { type, label, ... })
	 * ```
	 * When binding an object property the item's `initialValue` is read from
	 * `object[propertyName]` automatically.
	 *
	 * **Item config fields by type:**
	 *
	 * | type        | required fields                              | optional fields                        |
	 * |-------------|----------------------------------------------|----------------------------------------|
	 * | `slider`    | `label`, `min`, `max`                        | `step`, `easing`, `initialValue`       |
	 * | `select`    | `label`, `options` (array or `{key:label}`)  | `initialValue`                         |
	 * | `switch`    | `label`                                      | `initialValue` (boolean)               |
	 * | `button`    | `buttons` (string array)                     | `rowLabel`, `action` (Function)        |
	 * | `treeList`  | `label`, `tree` (nested object or array)     | `initialValue` (path array)            |
	 * | `separator` | —                                            | —                                      |
	 *
	 * To group controls under a collapsible header use {@link TabHandler#addFolder} instead.
	 *
	 * @function addItem
	 * @memberof TabHandler#
	 * @param {object|any}  arg1 - Item config object **or** the object to bind.
	 * @param {string}      [arg2] - Property name on `arg1` (signature 2 only).
	 * @param {object}      [arg3] - Item config overrides (signature 2 only).
	 * @returns {ItemHandler}
	 */
	me.addItem = function (arg1, arg2, arg3) {
		let params;

		if (arguments.length === 1) {
			params = arg1;
		} else {
			params = arg3 || {};
			params.object = arg1;
			params.propertyName = arg2;
			if (arg1 && typeof arg1 === 'object' && arg2 in arg1) {
				params.initialValue = arg1[arg2];
			} else if (arg3 && arg3.value !== undefined) {
				params.initialValue = arg3.initialValue;
			}
		}

		if (params.type === 'button' && Array.isArray(params.label)) {
			params.buttons = params.label;
			params.label = '';
		}

		return addFn(tabIndex, params);
	};

	/**
	 * Add a collapsible folder (visual group of controls) to this tab. Returns a
	 * {@link FolderHandler} — symmetric to `menu.addTab()` — through which you add or
	 * remove the folder's child controls.
	 *
	 * @function addFolder
	 * @memberof TabHandler#
	 * @param {string} label - Header text shown on the folder.
	 * @param {object} [opts] - Folder options.
	 * @param {boolean} [opts.collapsed=false] - Start collapsed (closed).
	 * @param {boolean} [opts.collapsible] - Allow click-to-collapse. Defaults to the
	 *   menu-wide `collapsibleFolders` option passed to `createMenu`.
	 * @returns {FolderHandler}
	 *
	 * @example
	 * const folder = tab.addFolder('Advanced');
	 * folder.addItem({ type: 'slider', label: 'Detail', min: 0, max: 10, step: 1 });
	 */
	me.addFolder = function (label, opts = {}) {
		const folderItemHandler = addFn(tabIndex, { type: 'folder', label, ...opts });
		return new FolderHandler(tabIndex, folderItemHandler.itemIndex, addFn, removeFn, folderItemHandler);
	};

	/**
	 * Remove an item from this tab.
	 * @function removeItem
	 * @memberof TabHandler#
	 * @param {ItemHandler} item - The handler returned by `addItem`.
	 */
	me.removeItem = function (item) {
		return removeFn(item);
	};
}

export { TabHandler };
