import React from 'react';

import Topbar from '../components/topbar';
import Panel from '../components/panel';
import Slider from '../components/slider';
import Select from '../components/select';
import Action from '../components/action';
import Switch from '../components/switch';
import Separator from '../components/separator';
import TreeList from '../components/treeList';
import Folder from '../components/folder';

import { orderItemsForDisplay } from '../utils/itemOrder';
import { getFocusNavigableKeys } from '../utils/focusableItems';

import PropTypes from 'prop-types';

const Mainmenu = ({
	tabs,
	currentTab,
	focus,
	updateIn,
	confirmOut,
	updateOutTemp,
	toggleTween,
	commitSlider,
	updateSelectValue,
	cycleValue,
	updateSwitchValue,
	callButtonAction,
	toggleFolder,
	collapsibleFolders = true,
	onClickTopbar,
}) => {
	const getFila = (tabIndex, k, item, idx) => {
		const isFocused = focus.area === 'panel' && focus.tabIndex === tabIndex && focus.controlIndex === idx;

		let label = '';
		if (item.hasOwnProperty('label') && item.label && item.label != '') {
			label = item.label;
		} else {
			if (item.propertyName && item.propertyName != '') {
				label = item.propertyName;
			}
		}
		switch (item.type) {
			case 'select':
				return (
					<Select
						key={k}
						tabIndex={tabIndex}
						itemIndex={k}
						label={label}
						value={item.value}
						options={item.options}
						onChange={updateSelectValue}
						onCycle={cycleValue}
						focused={isFocused}
					/>
				);
			case 'slider':
				return (
					<Slider
						key={k}
						tabIndex={tabIndex}
						itemIndex={k}
						label={label}
						step={item.step}
						easing={item.easing}
						min={item.min}
						max={item.max}
						in={item.in}
						inTarget={item.inTarget}
						out={item.outTemp}
						tween={item.tween}
						tweening={item.tweening}
						toggleTween={toggleTween}
						updateIn={updateIn}
						updateOutTemp={updateOutTemp}
						confirmOut={confirmOut}
					onCommit={commitSlider}
					focused={isFocused}
				/>
				);
			case 'button':
				return (
					<Action
						key={k}
						itemIndex={k}
						tabIndex={tabIndex}
						label={label}
						rowLabel={item.rowLabel}
						text={item.text}
						buttons={item.buttons}
						callButtonAction={callButtonAction}
						focused={isFocused}
						focusedButtonIndex={item.focusedButtonIndex || 0}
					/>
				);
			case 'switch':
				return (
					<Switch
						key={k}
						itemIndex={k}
						tabIndex={tabIndex}
						label={label}
						text={item.text}
						value={item.value}
						onChange={updateSwitchValue}
						focused={isFocused}
					/>
				);
			case 'folder':
				return (
					<Folder
						key={k}
						tabIndex={tabIndex}
						itemIndex={k}
						label={label}
						collapsed={item.collapsed}
						collapsible={item.collapsible ?? collapsibleFolders}
						onToggle={toggleFolder}
						focused={isFocused}
					/>
				);
			case 'separator':
				return <Separator key={k} itemIndex={k} tabIndex={tabIndex} />;
			case 'treeList':
				return (
					<TreeList
						key={k}
						tabIndex={tabIndex}
						itemIndex={k}
						label={label}
						tree={item.tree}
						value={item.value}
						onChange={updateSelectValue}
						focused={isFocused}
						focusPath={isFocused ? focus.tree?.path : []}
						focusLevel={isFocused ? focus.tree?.level : -1}
					/>
				);
			default:
				return null;
		}
	};

	// Renderizar los elementos según los ítems, en orden de display (cada carpeta
	// seguida de sus hijos). `idx` usa exclusivamente el orden de controles que
	// pueden recibir foco, para que separadores/ocultos/deshabilitados no desplacen
	// el resaltado. Los hijos de una carpeta se agrupan en `.folder-content`.
	const filas = [];
	const items = tabs[currentTab].items;
	const focusableKeys = getFocusNavigableKeys(items);
	const ordered = orderItemsForDisplay(items);

	for (let i = 0; i < ordered.length; i++) {
		const [key, item] = ordered[i];
		const idx = focusableKeys.indexOf(key);

		if (item.type === 'folder') {
			filas.push(getFila(currentTab, key, item, idx));

			const collapsible = item.collapsible ?? collapsibleFolders;
			const isOpen = !(collapsible && item.collapsed);

			// Reunir los hijos contiguos de esta carpeta.
			const childNodes = [];
			let j = i + 1;
			while (j < ordered.length && ordered[j][1].folderId === key) {
				if (isOpen) {
					const [ck, cItem] = ordered[j];
					childNodes.push(getFila(currentTab, ck, cItem, focusableKeys.indexOf(ck)));
				}
				j++;
			}
			i = j - 1; // saltar los hijos ya consumidos

			if (isOpen && childNodes.length) {
				filas.push(
					<div key={'fcont-' + key} className="folder-content">
						{childNodes}
					</div>
				);
			}
			continue;
		}

		// Ítem suelto de nivel superior (los hijos huérfanos también caen acá).
		filas.push(getFila(currentTab, key, item, idx));
	}

	return (
		<div id="mainmenu" className="mm">
			<Topbar active={currentTab} onClick={onClickTopbar} tabs={tabs} focus={focus} />
			<Panel nombre={tabs[currentTab].title} footer="">
				{filas}
			</Panel>
		</div>
	);
};

Mainmenu.propTypes = {
	tabs: PropTypes.object.isRequired,
	currentTab: PropTypes.string.isRequired,
	focus: PropTypes.object.isRequired,
	updateIn: PropTypes.func.isRequired,
	confirmOut: PropTypes.func.isRequired,
	updateOutTemp: PropTypes.func.isRequired,
	toggleTween: PropTypes.func.isRequired,
	commitSlider: PropTypes.func,
	updateSelectValue: PropTypes.func.isRequired,
	cycleValue: PropTypes.func.isRequired,
	updateSwitchValue: PropTypes.func.isRequired,
	callButtonAction: PropTypes.func.isRequired,
	toggleFolder: PropTypes.func,
	collapsibleFolders: PropTypes.bool,
	onClickTopbar: PropTypes.func.isRequired,
};

export default Mainmenu;
