import React, { useCallback } from 'react';
import Row from './row';
import PropTypes from 'prop-types';

const Switch = ({ tabIndex, itemIndex, label = '', value = false, onChange, focused = false }) => {
	const handleChange = useCallback(
		(e) => {
			const next = e.target.checked;
			// si tu parent antes toggleaba por índices, podés ignorar "next"
			onChange?.(tabIndex, itemIndex, next);
		},
		[onChange, tabIndex, itemIndex]
	);

	return (
		<Row focused={focused}>
			<div className="col col-md-9">
				<label
					className="switch"
					role="switch"
					aria-checked={value}
					data-checked={value ? 'true' : 'false'} // útil si usás MutationObserver
				>
					<input type="checkbox" checked={value} onChange={handleChange} />
					<span className="slider round"></span>
				</label>
				{label && <span className="switchText"> {label}</span>}
			</div>
		</Row>
	);
};

Switch.propTypes = {
	tabIndex: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
	itemIndex: PropTypes.oneOfType([PropTypes.number, PropTypes.string]),
	label: PropTypes.string,
	value: PropTypes.bool,
	onChange: PropTypes.func.isRequired,
	focused: PropTypes.bool,
};

export default React.memo(Switch);
