import { useCallback, useRef } from 'react';
import { easing } from '../functions/mappings';

/**
 * @description Custom hook to handle animations for sliders.
 */
export const useAnimation = (setState, updateDataSource) => {
	const timerRef = useRef(null);
	const frameRef = useRef(1);

	/**
	 * @description Stops the animation timer.
	 */
	const stopTimer = useCallback(() => {
		if (timerRef.current) {
			clearInterval(timerRef.current);
			timerRef.current = null;
		}
	}, []);

	/**
	 * @description Calculates the next state for a slider with tweening animation.
	 */
	const getUpdatedSliderWithTween = useCallback(
		(prevState, tabIndex, itemIndex, v, tweenSpeed) => {
			const item = prevState.tabs[tabIndex].items[itemIndex];

			const distance = v.inTarget - v.in;
			const inc = distance * tweenSpeed;

			if (Math.abs(distance) <= v.threshold) {
				v.in = v.inTarget;
				v.tweening = false;
			} else {
				v.in += inc;
			}

			const power = item.easing ?? 1;
			v.out = easing(v.in, item.min, item.max, power);

			//v.out = mappings[item.mode].out(v.in, item.min, item.max);
			v.outTemp = v.out;

			updateDataSource(tabIndex, itemIndex, v.out);

			return v;
		},
		[updateDataSource]
	);

	/**
	 * @description Calculates the next state for a slider with speed-based animation.
	 */
	const getUpdatedSliderWithSpeed = useCallback(
		(prevState, tabIndex, itemIndex, v, frame) => {
			const item = prevState.tabs[tabIndex].items[itemIndex];

			let every = 1;

			const signo = v.speed >= 0 ? 1 : -1;

			let inc = v.speed * Math.abs(item.max - item.min) * 0.01;

			if (item.step && item.step !== 0) {
				if (Math.abs(inc / item.step) < 1) {
					every = Math.min(60, Math.floor(Math.abs(item.step / inc)));
					inc = signo * Math.abs(item.step);
				} else {
					every = 1;
					inc = Math.floor(inc / item.step) * item.step;
				}
			}

			const doUpdate = frame % every === 0 || !item.hasOwnProperty('step');

			if (doUpdate) {
				v.in += inc;
				v.in = Math.max(Math.min(v.in, item.max), item.min);

				const power = item.easing ?? 1;
				v.out = easing(v.in, item.min, item.max, power);
				//v.out = mappings[item.mode].out(v.in, item.min, item.max);
				v.outTemp = v.out;

				updateDataSource(tabIndex, itemIndex, v.out);
			}

			return v;
		},
		[updateDataSource]
	);

	const tick = useCallback(() => {
		frameRef.current++;

		setState((prevState) => {
			const newState = { ...prevState };

			let noTweens = true;

			// Procesar todos los sliders con tween activado
			Object.keys(newState.tabs).forEach((tabIndex) => {
				const tab = newState.tabs[tabIndex];

				Object.keys(tab.items).forEach((itemIndex) => {
					const item = tab.items[itemIndex];

					if (item.type === 'slider') {
						if (item.tweening && item.tween) {
							// Si está en modo tween y tweening, actualizar
							const updatedItem = getUpdatedSliderWithTween(
								prevState,
								tabIndex,
								itemIndex,
								{ ...item },
								prevState.tweenSpeed
							);

							Object.assign(item, updatedItem);
							noTweens = false;
						} else if (item.speed && item.speed !== 0) {
							// Si tiene velocidad, actualizar con velocidad
							const updatedItem = getUpdatedSliderWithSpeed(
								prevState,
								tabIndex,
								itemIndex,
								{ ...item },
								frameRef.current
							);

							Object.assign(item, updatedItem);
							noTweens = false;
						}
					}
				});
			});

			// Si no hay tweens activos, detener el timer
			if (noTweens) {
				stopTimer();
			}

			return newState;
		});
	}, [getUpdatedSliderWithTween, getUpdatedSliderWithSpeed, stopTimer, setState]);

	/**
	 * @description Starts the animation timer to update sliders.
	 */
	const startTimer = useCallback(() => {
		if (!timerRef.current) {
			timerRef.current = setInterval(tick, 1000 / 60); // 60 fps
		}
	}, [tick]);

	return { startTimer, stopTimer, tick };
};
