import React from "react";
import PropTypes from "prop-types";

// Using default parameters instead of defaultProps
const Topbar = ({ tabs = {}, active, onClick, focus = {} }) => {
  const handleTabClick = (key) => {
    onClick(key);
  };

  // Generar las opciones del menú
  const opciones = Object.keys(tabs).map((key) => {
    const activeClass = active === key ? "active" : "";
    const value = tabs[key];

    return (
      <li className="nav-item" key={key}>
        <a
          className={`nav-link ${activeClass}`}
          href="#"
          onClick={(e) => {
            e.preventDefault();
            handleTabClick(key);
          }}
          data-toggle="tooltip"
          title={value.title}
          data-placement="top"
        >
          {value.icon && <i className={`fas ${value.icon}`}></i>}
        </a>
      </li>
    );
  });

  return <ul className={`nav nav-pills ${focus.area === "tabs" ? "focused" : ""}`}>{opciones}</ul>;
};

Topbar.propTypes = {
  tabs: PropTypes.object,
  active: PropTypes.string,
  onClick: PropTypes.func,
  focus: PropTypes.object,
};

// Removed defaultProps in favor of default parameters

export default Topbar;
