import React, { useState, useEffect, useCallback, useRef, forwardRef, useImperativeHandle, useMemo } from 'react';
import PropTypes from 'prop-types';

import Mainmenu from '../components/mainmenu';

import { useItemHandlers } from '../hooks/useItemHandlers';
import { useAnimation } from '../hooks/useAnimation';
import { useKeyboardEvents } from '../hooks/useKeyboardEvents';
import { useMenuActions } from '../hooks/useMenuActions';
import { useFocusNavigation } from '../hooks/useFocusNav';

import { sync as syncFunction } from '../functions/sync';
import { orderItemsForDisplay } from '../utils/itemOrder';
import { getFocusNavigableKeys } from '../utils/focusableItems';
import { PROTOCOL_VERSION } from '../protocol';

//import   '../styles/dynamicMenu.css';

/**
 * Resolve the internal focus path (index based) to an id-based snapshot the
 * CanvasRenderer can consume. Returns null when navigation is disabled or there
 * is no focus. The control index is resolved against the same visible-keys logic
 * the focus hook uses, so hidden/disabled items don't desync the cursor.
 */
function buildFocusSnapshot(focus, tabs, enabled) {
	if (!enabled || !focus) return null;
	if (focus.area === 'tabs') {
		return { area: 'tabs', tabId: focus.tabIndex };
	}
	const items = tabs[focus.tabIndex]?.items || {};
	const visibleKeys = getFocusNavigableKeys(items);
	return {
		area: 'panel',
		tabId: focus.tabIndex,
		itemId: visibleKeys[focus.controlIndex] ?? null,
		subIndex: focus.subIndex ?? null,
		treePath: focus.tree?.path ?? null,
		treeLevel: focus.tree?.level ?? null,
	};
}

const Maincontainer = forwardRef((props, ref) => {
	// Referencias
        const itemHandlersRef = useRef({});
        const pendingCallbackDispatchesRef = useRef([]);
        const didMountRef = useRef(false);
        const scheduledRef = useRef(false);

        // Canvas renderer event system
        const menuListenersRef = useRef(new Set());
        const emitMenuEventRef = useRef(null);

	// Estado
	const [state, setState] = useState({
		currentTab: undefined,
		tabs: {},
		isHidden: false,
		tweenSpeed: 0.01,
		collapsibleFolders: props.collapsibleFolders ?? true,
	});

	// Incremented by addItem / removeItem to reliably trigger structureChange
	const [structuralVersion, setStructuralVersion] = useState(0);

	// Variables
	const lastItemIndexRef = useRef(0);
	const lastTabIndexRef = useRef(0);

	// Emits an event to all subscribed canvas renderer listeners
	const emitMenuEvent = useCallback((evt) => {
		menuListenersRef.current.forEach((listener) => {
			try {
				listener(evt);
			} catch (e) {
				console.error('[DynamicMenu] listener error:', e);
			}
		});
	}, []);

	// Keep the ref always pointing to the latest emitMenuEvent
	emitMenuEventRef.current = emitMenuEvent;

	// Builds a serializable snapshot of a single item
	const buildItemSnapshot = useCallback((itemId, item) => {
		const base = {
			id: itemId,
			type: item.type,
			label: item.label ?? item.propertyName ?? '',
			disabled: item.disabled ?? false,
			folderId: item.folderId ?? null,
		};
		switch (item.type) {
			case 'folder':
				return {
					...base,
					collapsed: item.collapsed ?? false,
					collapsible: item.collapsible ?? state.collapsibleFolders ?? true,
				};
			case 'slider':
				return {
					...base,
					value: item.out ?? item.min ?? 0,
					min: item.min,
					max: item.max,
					step: item.step ?? null,
					listen: item.listen ?? false,
				};
			case 'select': {
				const rawOptions = item.options ?? [];
				const normalizedOptions = Array.isArray(rawOptions)
					? rawOptions.map((v) => ({ label: String(v), value: v }))
					: Object.entries(rawOptions).map(([k, v]) => ({ label: String(v), value: k }));
				const selectedIndex = normalizedOptions.findIndex((o) => o.value === item.value);
				return {
					...base,
					value: item.value,
					selectedIndex: selectedIndex === -1 ? 0 : selectedIndex,
					options: normalizedOptions,
				};
			}
			case 'switch':
				return {
					...base,
					value: item.value ?? false,
				};
			case 'button': {
				const buttonLabels = Array.isArray(item.buttons) ? item.buttons : [item.label ?? 'execute'];
				return {
					...base,
					buttons: buttonLabels.map((lbl, idx) => ({ id: 'b' + idx, label: lbl, active: false })),
				};
			}
			case 'treeList': {
				const path = item.value ?? [];
				const levels = [];
				let current = item.tree;
				let levelIdx = 0;
				while (current !== undefined) {
					if (Array.isArray(current)) {
						levels.push({
							level: levelIdx,
							options: current.map((opt) => ({ label: opt, active: opt === path[levelIdx] })),
						});
						break;
					} else if (current && typeof current === 'object') {
						const keys = Object.keys(current);
						levels.push({
							level: levelIdx,
							options: keys.map((k) => ({ label: k, active: k === path[levelIdx] })),
						});
						const nextKey = path[levelIdx];
						current = nextKey !== undefined ? current[nextKey] : undefined;
						levelIdx++;
					} else {
						break;
					}
				}
				return { ...base, path, levels, tree: item.tree };
			}
			default:
				return base;
		}
	}, [state.collapsibleFolders]);

	// Builds a full serializable snapshot of the entire menu state
	const buildMenuStateSnapshot = useCallback(() => {
		const tabEntries = Object.entries(state.tabs);
		const currentTabIndex = tabEntries.findIndex(([k]) => k === state.currentTab);
		const tabs = tabEntries.map(([tabId, tab], idx) => ({
			id: tabId,
			label: tab.title ?? '',
			icon: tab.icon ?? '',
			index: idx,
			items: orderItemsForDisplay(tab.items).map(([itemId, item]) => buildItemSnapshot(itemId, item)),
		}));
		return {
			version: PROTOCOL_VERSION,
			visible: !state.isHidden,
			currentTabId: state.currentTab,
			currentTabIndex: currentTabIndex === -1 ? 0 : currentTabIndex,
			collapsibleFolders: state.collapsibleFolders ?? true,
			tabs,
		};
	}, [state, buildItemSnapshot]);

	// Builds a snapshot of just the visible tab
	const buildVisibleTabState = useCallback(() => {
		const tabId = state.currentTab;
		if (!tabId || !state.tabs[tabId]) return null;
		const tab = state.tabs[tabId];
		const tabIndex = Object.keys(state.tabs).indexOf(tabId);
		return {
			id: tabId,
			label: tab.title ?? '',
			index: tabIndex,
			collapsibleFolders: state.collapsibleFolders ?? true,
			items: orderItemsForDisplay(tab.items).map(([itemId, item]) => buildItemSnapshot(itemId, item)),
		};
	}, [state, buildItemSnapshot]);

	const updateDataSource = useCallback(
		(tabIndex, itemIndex, value) => {
			const item = state.tabs[tabIndex].items[itemIndex];

			if (item.object && item.propertyName) {
				if (item.propertyName in item.object) {
					item.object[item.propertyName] = value;
				} else {
					console.warn(`Property '${item.propertyName}' does not exist on object`);
				}
			}

			if (itemHandlersRef.current[itemIndex]) {
				pendingCallbackDispatchesRef.current.push({
					callback: itemHandlersRef.current[itemIndex].dispatchOnChange,
					value,
				});
			}
		},
		[state.tabs]
	);

	const { startTimer, isTimerOn } = useAnimation(setState, updateDataSource);

        const signalStructuralChange = useCallback(() => setStructuralVersion((v) => v + 1), []);

        const {
                updateIn,
                confirmOut,
                updateOutTemp,
                toggleTween,
                commitSlider,
                updateSelectValue,
                updateSelectOptions,
                cycleValue,
                updateSwitchValue,
                callButtonAction,
                toggleFolder,
        } = useItemHandlers(setState, state, updateDataSource, startTimer, emitMenuEventRef, signalStructuralChange);

        const updateSelectOptionsRef = useRef(() => {});
        updateSelectOptionsRef.current = updateSelectOptions;

	// Focus based navigation hook (optional, enabled at construction time)
	const focusNavEnabled = props.focusNavigation ?? false;
	const {
		focus,
		moveUp,
		moveDown,
		moveLeft,
		moveRight,
		clickFocusedButton,
		activate,
		press,
		release,
		beginFocusedValueAdjustment,
		adjustFocusedValue,
		endFocusedValueAdjustment,
		deactivateFocusNavigation,
	} = useFocusNavigation(
		state,
		setState,
		{
			updateIn,
			commitSlider,
			updateSelectValue,
			updateSwitchValue,
			callButtonAction,
		},
		focusNavEnabled
	);

	// Full menu snapshot enriched with the id-based focus path (for CanvasRenderer).
	const getStateWithFocus = useCallback(
		() => ({
			...buildMenuStateSnapshot(),
			focus: buildFocusSnapshot(focus, state.tabs, focusNavEnabled),
		}),
		[buildMenuStateSnapshot, focus, state.tabs, focusNavEnabled]
	);

	// Emit a lightweight focusChange event whenever the cursor moves, so the
	// CanvasRenderer can repaint just the focus overlay (no layout recompute).
	const didMountForFocusRef = useRef(false);
	useEffect(() => {
		if (!focusNavEnabled) return;
		if (!didMountForFocusRef.current) {
			didMountForFocusRef.current = true;
			return;
		}
		emitMenuEvent({ type: 'focusChange', focus: buildFocusSnapshot(focus, state.tabs, focusNavEnabled) });
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [focus]);

	// Handlers
	const onClickTopbar = useCallback((k) => {
		setState((prevState) => ({
			...prevState,
			currentTab: k,
		}));
	}, []);

	const setVisible = useCallback((visible) => {
		setState((prevState) => ({
			...prevState,
			isHidden: !visible,
		}));
	}, []);

        const setCurrentTab = useCallback((tabId) => {
                if (tabId && state.tabs[tabId]) {
                        setState((prev) => ({ ...prev, currentTab: tabId }));
                }
        }, [state.tabs]);

        /**
         * Execute a logical command from an external source (e.g. CanvasRenderer).
         * Delegates to the same internal handlers used by the React UI so all side-effects
         * (data-source writes, onChange callbacks, canvas events) fire identically.
         *
         * Supported command types:
	 *   'pointer-interaction' - hide and reset the focus-navigation cursor
         *   'set-tab'        – { tabId }
         *   'cycle'          – { tabId, itemId, payload: { direction: 'prev'|'next' } }
         *   'toggle'         – { tabId, itemId }
         *   'activate'       – { tabId, itemId, payload: { buttonIndex, buttonLabel } }
         *   'set-slider-raw' – { tabId, itemId, payload: { rawValue, commit? } } (commit=false while dragging, omitted/true on release)
         *   'set-value'      – { tabId, itemId, payload: { value } } (select / treeList / switch)
         */
        const executeCommand = useCallback((cmd) => {
                if (!cmd?.type) return;
                const { tabId, itemId, payload } = cmd;
                switch (cmd.type) {
			case 'pointer-interaction':
				deactivateFocusNavigation();
				break;
                        case 'set-tab':
                                if (tabId && state.tabs[tabId]) {
                                        setState((prev) => ({ ...prev, currentTab: tabId }));
                                }
                                break;
                        case 'cycle':
                                cycleValue(tabId, itemId, payload?.direction === 'prev' ? 'prev' : 'next');
                                break;
                        case 'toggle':
                                updateSwitchValue(tabId, itemId);
                                break;
                        case 'toggle-folder':
                                toggleFolder(tabId, itemId);
                                break;
                        case 'activate':
                                callButtonAction(tabId, itemId, payload?.buttonIndex ?? 0, payload?.buttonLabel ?? '');
                                break;
                        case 'set-slider-raw':
                                if (payload?.rawValue === undefined) break;
                                updateIn(tabId, itemId, payload.rawValue);
                                if (payload?.commit !== false) commitSlider(tabId, itemId, payload.rawValue);
                                break;
                        case 'set-value': {
                                if (payload?.value === undefined) break;
                                const item = state.tabs[tabId]?.items[itemId];
                                if (!item) break;
                                if (item.type === 'select' || item.type === 'treeList') {
                                        updateSelectValue(tabId, itemId, payload.value);
                                } else if (item.type === 'switch' && item.value !== !!payload.value) {
                                        updateSwitchValue(tabId, itemId);
                                }
                                break;
                        }
                        default:
                                break;
                }
        }, [state.tabs, setState, cycleValue, updateSwitchValue, callButtonAction, updateIn, commitSlider, updateSelectValue, toggleFolder, deactivateFocusNavigation]);

	// Esta funcionalidad queda desactivada por ahora
	// voy a usar ValueProxies para manejarlo

	/*
	const { addKeyboardHandler } = useKeyboardEvents(state, {
		updateSwitchValue,
		callButtonAction,
		cycleValue,
		updateIn,
		setVisible,
	});
        */

        const { addTab, removeTab } = useMenuActions(
                setState,
                //addKeyboardHandler,
                itemHandlersRef,
                lastItemIndexRef,
                lastTabIndexRef,
                updateSelectOptionsRef,
                signalStructuralChange
        );

	const dispatchPendingCallbacks = useCallback(() => {
		pendingCallbackDispatchesRef.current.forEach((element) => {
			element.callback(element.value);
		});
		pendingCallbackDispatchesRef.current = [];
	}, []);

        const sync = useCallback(() => {
                syncFunction(itemHandlersRef, pendingCallbackDispatchesRef)(setState);
        }, []);

        const renderSignature = useMemo(() => {
                const tabs = {};
                Object.entries(state.tabs).forEach(([tabKey, tab]) => {
                        const items = {};
                        Object.entries(tab.items || {}).forEach(([itemKey, item]) => {
                                items[itemKey] = {
                                        value: item.value,
                                        hidden: item.hidden,
                                        disabled: item.disabled,
                                        focusedButtonIndex: item.focusedButtonIndex,
                                };

                                if (item.type === 'slider') {
                                        items[itemKey] = {
                                                ...items[itemKey],
                                                in: item.in,
                                                inTarget: item.inTarget,
                                                out: item.out,
                                                outTemp: item.outTemp,
                                                tween: item.tween,
                                                tweening: item.tweening,
                                        };
                                }
                        });
                        tabs[tabKey] = { items };
                });
                return JSON.stringify({
                        currentTab: state.currentTab,
                        isHidden: state.isHidden,
                        tabs,
                        focus,
                        isTimerOn,
                });
        }, [state, focus, isTimerOn]);

	// Efectos para manejar callbacks pendientes
        useEffect(() => {
                dispatchPendingCallbacks();
        }, [state, dispatchPendingCallbacks]);

        // onUiChange indica que hubo cambios visuales en el menu; el host decide cuando capturar en su propio rAF.
        useEffect(() => {
                if (!didMountRef.current) {
                        didMountRef.current = true;
                        if (!props.notifyOnMount) return;
                }
                if (!props.onUiChange) return;
                if (scheduledRef.current) return;
                scheduledRef.current = true;

                const schedule = typeof queueMicrotask === 'function' ? queueMicrotask : (cb) => Promise.resolve().then(cb);

                schedule(() => {
                        scheduledRef.current = false;
                        props.onUiChange?.({ ts: performance.now() });
                });
        }, [renderSignature, props.onUiChange, props.notifyOnMount]);

        // Tracks structural identity of the menu (tabs/items/options) for structureChange detection
        const structureSignature = useMemo(() => {
                const tabData = Object.entries(state.tabs).map(([tabId, tab]) => ({
                        id: tabId,
                        items: Object.entries(tab.items || {}).map(([itemId, item]) => ({
                                id: itemId,
                                type: item.type,
                                // Include select options so updateSelectOptions triggers structureChange
                                options: item.type === 'select' ? item.options : undefined,
                        })),
                }));
                return JSON.stringify(tabData);
        }, [state.tabs]);

        // Tracks the initial mount to avoid emitting on first render
        const didMountForEventsRef = useRef(false);
        const didMountForStructuralRef = useRef(false);

        // Emit tabChange when the active tab changes (after initial mount)
        useEffect(() => {
                if (!didMountForEventsRef.current) return;
                if (!state.currentTab) return;
                const tabIndex = Object.keys(state.tabs).indexOf(state.currentTab);
                emitMenuEvent({
                        type: 'tabChange',
                        currentTabId: state.currentTab,
                        currentTabIndex: tabIndex,
                        state: getStateWithFocus(),
                });
        // eslint-disable-next-line react-hooks/exhaustive-deps
        }, [state.currentTab]);

        // Emit structureChange when tabs/items/options change (after initial mount)
        useEffect(() => {
                if (!didMountForEventsRef.current) {
                        didMountForEventsRef.current = true;
                        return;
                }
                emitMenuEvent({
                        type: 'structureChange',
                        reason: 'update',
                        state: getStateWithFocus(),
                });
        // eslint-disable-next-line react-hooks/exhaustive-deps
        }, [structureSignature]);

        // Emit structureChange when addItem / removeItem are called (after initial mount).
        // Uses structuralVersion because state.tabs reference never changes (shallow-copy setState),
        // so useMemo([state.tabs]) cannot detect item additions/removals.
        useEffect(() => {
                if (!didMountForStructuralRef.current) {
                        didMountForStructuralRef.current = true;
                        return;
                }
                emitMenuEvent({
                        type: 'structureChange',
                        reason: 'update',
                        state: getStateWithFocus(),
                });
        // eslint-disable-next-line react-hooks/exhaustive-deps
        }, [structuralVersion]);

        // Emit visibilityChange when isHidden changes (after initial mount)
        const prevIsHiddenRef = useRef(state.isHidden);
        useEffect(() => {
                if (prevIsHiddenRef.current === state.isHidden) return;
                prevIsHiddenRef.current = state.isHidden;
                emitMenuEvent({ type: 'visibilityChange', visible: !state.isHidden });
        // eslint-disable-next-line react-hooks/exhaustive-deps
        }, [state.isHidden]);

	// Exponer métodos a través de la referencia usando useImperativeHandle
	useImperativeHandle(
		ref,
		() => ({
                        addTab,
                        removeTab,
                        sync,
                        setVisible,
                        moveUp,
                        moveDown,
                        moveLeft,
                        moveRight,
			clickFocusedButton,
                        activate,
                        press,
                        release,
			beginFocusedValueAdjustment,
			adjustFocusedValue,
			endFocusedValueAdjustment,
			deactivateFocusNavigation,
                        isFocusNavEnabled: () => focusNavEnabled,
                        updateSelectOptions,
                        // Contract version shared with CanvasRenderer (see ../protocol.js)
                        protocolVersion: PROTOCOL_VERSION,
                        // New: snapshot and event API
                        getMenuState: () => getStateWithFocus(),
                        getVisibleTabState: () => buildVisibleTabState(),
                        subscribe: (listener) => {
                                menuListenersRef.current.add(listener);
                                return () => menuListenersRef.current.delete(listener);
                        },
                        unsubscribe: (listener) => {
                                menuListenersRef.current.delete(listener);
                        },
                        // Command API for canvas / VR integration
                        executeCommand,
                        setCurrentTab,
                }),
		[addTab, removeTab, sync, moveUp, moveDown, moveLeft, moveRight, clickFocusedButton, activate, press, release, beginFocusedValueAdjustment, adjustFocusedValue, endFocusedValueAdjustment, deactivateFocusNavigation, focusNavEnabled, updateSelectOptions, buildMenuStateSnapshot, buildVisibleTabState, getStateWithFocus, executeCommand, setCurrentTab]
        );

	// Renderizado
	if (state.isHidden) {
		return null;
	}

	return (
		<div
			className={`mainContainer ${state.isHidden ? 'hidden' : ''}`}
			onPointerDownCapture={deactivateFocusNavigation}
		>
			{state.currentTab !== undefined && (
				<Mainmenu
					tabs={state.tabs}
					currentTab={state.currentTab}
					focus={focus || {}}
					timerOn={isTimerOn}
					updateIn={updateIn}
					confirmOut={confirmOut}
					updateOutTemp={updateOutTemp}
					toggleTween={toggleTween}
					commitSlider={commitSlider}
					updateSelectValue={updateSelectValue}
					cycleValue={cycleValue}
					updateSwitchValue={updateSwitchValue}
					callButtonAction={callButtonAction}
					toggleFolder={toggleFolder}
					collapsibleFolders={state.collapsibleFolders ?? true}
					onClickTopbar={onClickTopbar}
				/>
			)}
		</div>
	);
});

Maincontainer.propTypes = {
        onUiChange: PropTypes.func,
        notifyOnMount: PropTypes.bool,
        collapsibleFolders: PropTypes.bool,
        focusNavigation: PropTypes.bool,
};

export default Maincontainer;
